INSERT INTO "ParticleExercise" ("id", "level", "japanese", "reading", "translation", "correctParticle", "options", "explanation") VALUES ('p-1', 'N5', '私 [blank] 田中と申します。', 'わたし [blank] たなかともうします。', 'I am Tanaka (humble).', 'は', '["は","が","を","に"]', '「は」(wa) is the topic marker indicating what the sentence is about (the topic ''As for me...'').') ON CONFLICT DO NOTHING;
INSERT INTO "ParticleExercise" ("id", "level", "japanese", "reading", "translation", "correctParticle", "options", "explanation") VALUES ('p-2', 'N5', '毎朝７時 [blank] 起きます。', 'まいあさ ななじ [blank] おきます。', 'I wake up at 7 o''clock every morning.', 'に', '["に","で","を","へ"]', '「に」(ni) marks a specific numerical point in time at which an action occurs.') ON CONFLICT DO NOTHING;
INSERT INTO "ParticleExercise" ("id", "level", "japanese", "reading", "translation", "correctParticle", "options", "explanation") VALUES ('p-3', 'N5', '図書館 [blank] 本を読みます。', 'としょかん [blank] ほんをよみます。', 'I read books at the library.', 'で', '["で","に","を","へ"]', '「で」(de) marks the location where an action takes place.') ON CONFLICT DO NOTHING;
INSERT INTO "ParticleExercise" ("id", "level", "japanese", "reading", "translation", "correctParticle", "options", "explanation") VALUES ('p-4', 'N5', 'りんご [blank] 食べました。', 'りんご [blank] たべました。', 'I ate an apple.', 'を', '["を","は","が","に"]', '「を」(o/wo) marks the direct object of a transitive action verb.') ON CONFLICT DO NOTHING;
INSERT INTO "ParticleExercise" ("id", "level", "japanese", "reading", "translation", "correctParticle", "options", "explanation") VALUES ('p-5', 'N5', '明日、東京 [blank] 行きます。', 'あした、とうきょう [blank] いきます。', 'Tomorrow, I will go to Tokyo.', 'へ', '["へ","で","を","が"]', '「へ」(e) marks the direction or destination of movement verbs (行く, 来る, 帰る).') ON CONFLICT DO NOTHING;
INSERT INTO "ParticleExercise" ("id", "level", "japanese", "reading", "translation", "correctParticle", "options", "explanation") VALUES ('p-6', 'N5', '友達 [blank] 一緒に映画を見ました。', 'ともだち [blank] いっしょに えいがを みました。', 'I watched a movie together with my friend.', 'と', '["と","に","で","を"]', '「と」(to) indicates companionship or doing an action ''together with'' someone.') ON CONFLICT DO NOTHING;
INSERT INTO "ParticleExercise" ("id", "level", "japanese", "reading", "translation", "correctParticle", "options", "explanation") VALUES ('p-7', 'N5', '日本語の辞書 [blank] ありません。', 'にほんごの じしょ [blank] ありません。', 'There is no Japanese dictionary.', 'が', '["が","を","で","へ"]', 'With the existence verbs ある (inanimate) and いる (animate), the existing subject is marked with 「が」(ga).') ON CONFLICT DO NOTHING;
INSERT INTO "ParticleExercise" ("id", "level", "japanese", "reading", "translation", "correctParticle", "options", "explanation") VALUES ('p-8', 'N5', '電車 [blank] 大学へ通っています。', 'でんしゃ [blank] だいがくへ かよっています。', 'I commute to university by train.', 'で', '["で","に","を","と"]', '「で」(de) marks the means or instrument used to perform an action (by train, by car, with chopsticks).') ON CONFLICT DO NOTHING;
INSERT INTO "ParticleExercise" ("id", "level", "japanese", "reading", "translation", "correctParticle", "options", "explanation") VALUES ('p-9', 'N5', '田中さん [blank] 英語を教えました。', 'たなかさん [blank] えいごを おしえました。', 'I taught English to Mr. Tanaka.', 'に', '["に","で","を","から"]', '「に」(ni) indicates the recipient or indirect object of an action (giving, teaching, lending to someone).') ON CONFLICT DO NOTHING;
INSERT INTO "ParticleExercise" ("id", "level", "japanese", "reading", "translation", "correctParticle", "options", "explanation") VALUES ('p-10', 'N5', '駅 [blank] 家まで歩いて１０分です。', 'えき [blank] うちまで あるいて じゅっぷんです。', 'It is a 10-minute walk from the station to my house.', 'から', '["から","まで","より","に"]', '「から」(kara) indicates the starting point of time or physical location (''from X'').') ON CONFLICT DO NOTHING;
INSERT INTO "ParticleExercise" ("id", "level", "japanese", "reading", "translation", "correctParticle", "options", "explanation") VALUES ('p-11', 'N4', '雨 [blank] 降っているので、傘を持っていきます。', 'あめ [blank] ふっているので、かさを もっていきます。', 'Because it''s raining, I will take an umbrella.', 'が', '["が","を","は","で"]', 'Natural phenomena (rain, snow, wind) take the subject marker 「が」(ga) with verbs like 降る or 吹く.') ON CONFLICT DO NOTHING;
INSERT INTO "ParticleExercise" ("id", "level", "japanese", "reading", "translation", "correctParticle", "options", "explanation") VALUES ('p-12', 'N4', '新幹線はバス [blank] 速いです。', 'しんかんせんは バス [blank] はやいです。', 'The Shinkansen is faster than a bus.', 'より', '["より","ほど","から","と"]', '「より」(yori) indicates the baseline / standard of comparison (''faster than X'').') ON CONFLICT DO NOTHING;
INSERT INTO "ParticleExercise" ("id", "level", "japanese", "reading", "translation", "correctParticle", "options", "explanation") VALUES ('p-13', 'N4', 'この部屋はあの部屋 [blank] 広くないです。', 'このへやは あのへや [blank] ひろくないです。', 'This room is not as spacious as that room.', 'ほど', '["ほど","より","だけ","しか"]', '「ほど〜ない」(hodo... nai) expresses ''not as... as X'' in negative comparisons.') ON CONFLICT DO NOTHING;
INSERT INTO "ParticleExercise" ("id", "level", "japanese", "reading", "translation", "correctParticle", "options", "explanation") VALUES ('p-14', 'N4', '財布の中に１００円 [blank] ありません。', 'さいふの なかに ひゃくえん [blank] ありません。', 'I only have 100 yen in my wallet (nothing more).', 'しか', '["しか","だけ","も","より"]', '「しか」(shika) pairs strictly with negative verbs to mean ''nothing except / only''.') ON CONFLICT DO NOTHING;
INSERT INTO "ParticleExercise" ("id", "level", "japanese", "reading", "translation", "correctParticle", "options", "explanation") VALUES ('p-15', 'N4', '先生 [blank] 褒められて、とても嬉しかったです。', 'せんせい [blank] ほめられて、とても うれしかったです。', 'I was praised by my teacher and felt very happy.', 'に', '["に","で","を","から"]', 'In passive voice constructions (受け身), the agent who performs the action upon the subject is marked with 「に」(ni).') ON CONFLICT DO NOTHING;
INSERT INTO "ParticleExercise" ("id", "level", "japanese", "reading", "translation", "correctParticle", "options", "explanation") VALUES ('p-16', 'N4', '日本料理の中 [blank] 、寿司が一番好きです。', 'にほんりょうりの なか [blank] 、すしが いちばん すきです。', 'Among Japanese dishes, I like sushi the most.', 'で', '["で","に","から","は"]', '「の中で」(no naka de) specifies the scope or category within which a superlative choice is made.') ON CONFLICT DO NOTHING;
INSERT INTO "ParticleExercise" ("id", "level", "japanese", "reading", "translation", "correctParticle", "options", "explanation") VALUES ('p-17', 'N3', '彼 [blank] 対して、親切に接するべきです。', 'かれ [blank] たいして、しんせつに せっするべきです。', 'You should treat him kindly.', 'に', '["に","を","で","と"]', 'The grammar pattern 「〜に対して」(ni taishite) means ''towards / in regard to / facing''.') ON CONFLICT DO NOTHING;
INSERT INTO "ParticleExercise" ("id", "level", "japanese", "reading", "translation", "correctParticle", "options", "explanation") VALUES ('p-18', 'N3', '日本の歴史 [blank] ついて論文を書きました。', 'にほんの れきし [blank] ついて ろんぶんを かきました。', 'I wrote a thesis about Japanese history.', 'に', '["に","を","で","へ"]', 'The compound particle pattern 「〜について」(ni tsuite) means ''about / regarding''.') ON CONFLICT DO NOTHING;
INSERT INTO "ParticleExercise" ("id", "level", "japanese", "reading", "translation", "correctParticle", "options", "explanation") VALUES ('p-19', 'N3', '台風 [blank] よって、多くの電車が止まりました。', 'たいふう [blank] よって、おおくの でんしゃが とまりました。', 'Due to the typhoon, many trains were stopped.', 'に', '["に","で","を","と"]', '「〜によって」(ni yotte) expresses cause, reason, or means (''due to / by means of'').') ON CONFLICT DO NOTHING;
INSERT INTO "ParticleExercise" ("id", "level", "japanese", "reading", "translation", "correctParticle", "options", "explanation") VALUES ('p-20', 'N3', '年齢 [blank] かかわらず、誰でも参加できます。', 'ねんれい [blank] かかわらず、だれでも さんかできます。', 'Regardless of age, anyone can participate.', 'に', '["に","を","で","は"]', '「〜にかかわらず」(ni kakawarazu) means ''regardless of / without distinction of''.') ON CONFLICT DO NOTHING;
INSERT INTO "ParticleExercise" ("id", "level", "japanese", "reading", "translation", "correctParticle", "options", "explanation") VALUES ('p-21', 'N3', '子供 [blank] とって、遊びは大切な学びの場です。', 'こども [blank] とって、あそびは たいせつな まなびの ばです。', 'For children, play is an important place of learning.', 'に', '["に","を","で","と"]', '「〜にとって」(ni totte) means ''for / from the perspective of''.') ON CONFLICT DO NOTHING;
INSERT INTO "ParticleExercise" ("id", "level", "japanese", "reading", "translation", "correctParticle", "options", "explanation") VALUES ('p-22', 'N3', '期待 [blank] 応えて、優勝することができました。', 'きたい [blank] こたえて、ゆうしょうすることが できました。', 'In response to their expectations, we were able to win first prize.', 'に', '["に","を","へ","で"]', '「〜に応えて」(ni kotaete) means ''in response to / meeting (expectations, requests)''.') ON CONFLICT DO NOTHING;
INSERT INTO "ScrambleExercise" ("id", "level", "fullSentence", "reading", "translation", "tiles") VALUES ('sc-1', 'N5', '私は毎朝コーヒーを飲みます。', 'わたしは まいあさ こーひーを のみます。', 'I drink coffee every morning.', '["私は","毎朝","コーヒーを","飲みます。"]') ON CONFLICT DO NOTHING;
INSERT INTO "ScrambleExercise" ("id", "level", "fullSentence", "reading", "translation", "tiles") VALUES ('sc-2', 'N5', '日曜日にお母さんとデパートへ行きました。', 'にちようびに おかあさんと でぱーとへ いきました。', 'I went to the department store with my mother on Sunday.', '["日曜日に","お母さんと","デパートへ","行きました。"]') ON CONFLICT DO NOTHING;
INSERT INTO "ScrambleExercise" ("id", "level", "fullSentence", "reading", "translation", "tiles") VALUES ('sc-3', 'N5', '机の上に新しい本があります。', 'つくえのうえに あたらしいほんが あります。', 'There is a new book on top of the desk.', '["机の上に","新しい","本が","あります。"]') ON CONFLICT DO NOTHING;
INSERT INTO "ScrambleExercise" ("id", "level", "fullSentence", "reading", "translation", "tiles") VALUES ('sc-4', 'N5', '田中さんは図書館で日本語を勉強します。', 'たなかさんは としょかんで にほんごを べんきょうします。', 'Mr. Tanaka studies Japanese at the library.', '["田中さんは","図書館で","日本語を","勉強します。"]') ON CONFLICT DO NOTHING;
INSERT INTO "ScrambleExercise" ("id", "level", "fullSentence", "reading", "translation", "tiles") VALUES ('sc-5', 'N5', '昨日友達と一緒に美味しいラーメンを食べました。', 'きのう ともだちと いっしょに おいしいらーめんを たべました。', 'Yesterday, I ate delicious ramen together with my friend.', '["昨日","友達と一緒に","美味しいラーメンを","食べました。"]') ON CONFLICT DO NOTHING;
INSERT INTO "ScrambleExercise" ("id", "level", "fullSentence", "reading", "translation", "tiles") VALUES ('sc-6', 'N5', '私の部屋には大きなテレビがあります。', 'わたしのへやには おおきなてれびが あります。', 'There is a large television in my room.', '["私の部屋には","大きな","テレビが","あります。"]') ON CONFLICT DO NOTHING;
INSERT INTO "ScrambleExercise" ("id", "level", "fullSentence", "reading", "translation", "tiles") VALUES ('sc-7', 'N4', '日本語が上手に話せるようになりたいです。', 'にほんごが じょうずに はなせるように なりたいです。', 'I want to become able to speak Japanese fluently.', '["日本語が","上手に","話せるように","なりたいです。"]') ON CONFLICT DO NOTHING;
INSERT INTO "ScrambleExercise" ("id", "level", "fullSentence", "reading", "translation", "tiles") VALUES ('sc-8', 'N4', '宿題を忘れないようにメモをしておきます。', 'しゅくだいを わすれないように めもを しておきます。', 'I will make a note so that I don''t forget my homework.', '["宿題を","忘れないように","メモを","しておきます。"]') ON CONFLICT DO NOTHING;
INSERT INTO "ScrambleExercise" ("id", "level", "fullSentence", "reading", "translation", "tiles") VALUES ('sc-9', 'N4', '来週のテストのために毎晩遅くまで復習しています。', 'らいしゅうの てすとのために まいばん おそくまで ふくしゅうしています。', 'For next week''s test, I am reviewing late every night.', '["来週のテストのために","毎晩","遅くまで","復習しています。"]') ON CONFLICT DO NOTHING;
INSERT INTO "ScrambleExercise" ("id", "level", "fullSentence", "reading", "translation", "tiles") VALUES ('sc-10', 'N4', '雨が降るかもしれないので傘を持って行きます。', 'あめが ふるかもしれないので かさを もって いきます。', 'Because it might rain, I will take an umbrella.', '["雨が","降るかもしれないので","傘を","持って行きます。"]') ON CONFLICT DO NOTHING;
INSERT INTO "ScrambleExercise" ("id", "level", "fullSentence", "reading", "translation", "tiles") VALUES ('sc-11', 'N4', '先生に質問があるなら早く聞いたほうがいいですよ。', 'せんせいに しつもんがあるなら はやく きいたほうが いいですよ。', 'If you have a question for the teacher, you had better ask soon.', '["先生に","質問があるなら","早く","聞いたほうがいいですよ。"]') ON CONFLICT DO NOTHING;
INSERT INTO "ScrambleExercise" ("id", "level", "fullSentence", "reading", "translation", "tiles") VALUES ('sc-12', 'N3', '健康のために毎日野菜をたくさん食べることにしています。', 'けんこうのために まいにち やさいを たくさん たべることに しています。', 'For my health, I make it a rule to eat a lot of vegetables every day.', '["健康のために","毎日","野菜をたくさん","食べることに","しています。"]') ON CONFLICT DO NOTHING;
INSERT INTO "ScrambleExercise" ("id", "level", "fullSentence", "reading", "translation", "tiles") VALUES ('sc-13', 'N3', '日本に住んでいるうちに色々な名所を訪れたいです。', 'にほんに すんでいるうちに いろいろな めいしょを おとずれたいです。', 'While I am living in Japan, I want to visit various famous spots.', '["日本に","住んでいるうちに","色々な名所を","訪れたいです。"]') ON CONFLICT DO NOTHING;
INSERT INTO "ScrambleExercise" ("id", "level", "fullSentence", "reading", "translation", "tiles") VALUES ('sc-14', 'N3', '長時間の会議の末にようやく新しい方針が決まりました。', 'ちょうじかんの かいぎのすえに ようやく あたらしいほうしんが きまりました。', 'After a long meeting, the new policy was finally decided.', '["長時間の会議の末に","ようやく","新しい方針が","決まりました。"]') ON CONFLICT DO NOTHING;
INSERT INTO "ScrambleExercise" ("id", "level", "fullSentence", "reading", "translation", "tiles") VALUES ('sc-15', 'N3', '努力したおかげで希望の大学に合格することができました。', 'どりょくしたおかげで きぼうの だいがくに ごうかくすることが できました。', 'Thanks to my hard work, I was able to pass the entrance exam of my desired university.', '["努力したおかげで","希望の大学に","合格することが","できました。"]') ON CONFLICT DO NOTHING;
INSERT INTO "GrammarPatternExercise" ("id", "level", "scenario", "sentence", "correctPattern", "options", "meaning", "explanation") VALUES ('gp-1', 'N5', 'You are asking permission to take a photo in a museum.', 'ここで写真を撮って___いいですか。', '〜てもいい', '["〜てもいい","〜てはいけない","〜てください","〜てから"]', 'Expressing permission (May I / Is it okay to...?)', 'Verb [Te-form] + もいいですか is used to ask polite permission to do something.') ON CONFLICT DO NOTHING;
INSERT INTO "GrammarPatternExercise" ("id", "level", "scenario", "sentence", "correctPattern", "options", "meaning", "explanation") VALUES ('gp-2', 'N5', 'Giving helpful health advice to someone running a fever.', '熱があるなら、早く寝た___。', '〜ほうがいい', '["〜ほうがいい","〜てはいけない","〜たり〜たり","〜ことができる"]', 'Giving advice / recommendation (It''s better to...)', 'Verb [Ta-form] + ほうがいい expresses strong yet thoughtful advice or recommendations.') ON CONFLICT DO NOTHING;
INSERT INTO "GrammarPatternExercise" ("id", "level", "scenario", "sentence", "correctPattern", "options", "meaning", "explanation") VALUES ('gp-3', 'N5', 'Prohibiting someone from smoking in a non-smoking area.', 'ここでタバコを吸っ___。', '〜てはいけない', '["〜てはいけない","〜てもいい","〜たほうがいい","〜てみる"]', 'Strict prohibition (Must not / You cannot...)', 'Verb [Te-form] + ははいけません / ははいけない expresses strict prohibition.') ON CONFLICT DO NOTHING;
INSERT INTO "GrammarPatternExercise" ("id", "level", "scenario", "sentence", "correctPattern", "options", "meaning", "explanation") VALUES ('gp-4', 'N5', 'Describing listing multiple representative actions on your day off.', '休みの日は本を読ん___、映画を見___します。', '〜たり〜たりする', '["〜たり〜たりする","〜ながら","〜てから","〜てもいい"]', 'Listing representative actions (Doing things like X and Y)', 'Verb [Ta-form] + り + Verb [Ta-form] + りする lists non-exhaustive activities.') ON CONFLICT DO NOTHING;
INSERT INTO "GrammarPatternExercise" ("id", "level", "scenario", "sentence", "correctPattern", "options", "meaning", "explanation") VALUES ('gp-5', 'N4', 'Explaining an action done in advance for future preparation.', 'パーティーの前に部屋を掃除して___。', '〜ておく', '["〜ておく","〜てしまう","〜てみる","〜ていく"]', 'Doing something in advance for preparation', 'Verb [Te-form] + おく (oku) means to perform an action in advance for a future purpose.') ON CONFLICT DO NOTHING;
INSERT INTO "GrammarPatternExercise" ("id", "level", "scenario", "sentence", "correctPattern", "options", "meaning", "explanation") VALUES ('gp-6', 'N4', 'Expressing regret after accidentally leaving your wallet on the train.', '財布を電車の中に忘れて___。', '〜てしまう', '["〜てしまう","〜ておく","〜てくる","〜ている"]', 'Expressing completion with regret / accidentally doing something', 'Verb [Te-form] + しまう (shimau) conveys completion of an action with regret or unintended consequences.') ON CONFLICT DO NOTHING;
INSERT INTO "GrammarPatternExercise" ("id", "level", "scenario", "sentence", "correctPattern", "options", "meaning", "explanation") VALUES ('gp-7', 'N4', 'Attempting to eat spicy wasabi for the very first time to see what it''s like.', '本場のわさびを少し食べ___。', '〜てみる', '["〜てみる","〜ておく","〜てしまう","〜てくる"]', 'Trying something out to see how it is (give it a try)', 'Verb [Te-form] + みる (miru) means to do an action as a trial or experiment.') ON CONFLICT DO NOTHING;
INSERT INTO "GrammarPatternExercise" ("id", "level", "scenario", "sentence", "correctPattern", "options", "meaning", "explanation") VALUES ('gp-8', 'N4', 'Describing multitasking: listening to music while studying.', '音楽を聴き___勉強するのが好きです。', '〜ながら', '["〜ながら","〜たあとで","〜てから","〜とおりに"]', 'Simultaneous actions (While doing X, doing Y)', 'Verb [Masu-stem] + ながら (nagara) indicates two actions performed simultaneously by the same subject.') ON CONFLICT DO NOTHING;
INSERT INTO "GrammarPatternExercise" ("id", "level", "scenario", "sentence", "correctPattern", "options", "meaning", "explanation") VALUES ('gp-9', 'N4', 'Declaring your intention to study abroad in Japan next year.', '来年、日本へ留学し___と思っています。', '〜ようと思う', '["〜ようと思う","〜てしまう","〜たばかり","〜はずだ"]', 'Expressing one''s volition / intention (Thinking of doing...)', 'Verb [Volitional form] + と思う expresses intention or plans formed in the speaker''s mind.') ON CONFLICT DO NOTHING;
INSERT INTO "GrammarPatternExercise" ("id", "level", "scenario", "sentence", "correctPattern", "options", "meaning", "explanation") VALUES ('gp-10', 'N3', 'Stating a condition that is strictly essential for an experiment to proceed.', '先生の許可が___、この実験はできません。', '〜ないことには', '["〜ないことには","〜に反して","〜に応じて","〜ばかりか"]', 'Unless / Without doing X, Y cannot happen', 'Verb [Nai-form] + ことには expresses ''unless X happens, Y cannot be realized''.') ON CONFLICT DO NOTHING;
INSERT INTO "GrammarPatternExercise" ("id", "level", "scenario", "sentence", "correctPattern", "options", "meaning", "explanation") VALUES ('gp-11', 'N3', 'Expressing gratitude that thanks to the teacher''s guidance, you passed.', '先生のご指導の___、合格することができました。', '〜おかげで', '["〜おかげで","〜せいで","〜わりに","〜くせに"]', 'Thanks to (positive cause and beneficial outcome)', 'Noun + の / Verb plain + おかげで expresses gratitude for a positive result.') ON CONFLICT DO NOTHING;
INSERT INTO "GrammarPatternExercise" ("id", "level", "scenario", "sentence", "correctPattern", "options", "meaning", "explanation") VALUES ('gp-12', 'N3', 'Blaming a sudden delay on the heavy rainstorm.', '大雨の___、電車が大幅に遅れてしまいました。', '〜せいで', '["〜せいで","〜おかげで","〜につれて","〜反面"]', 'Because of / Blame on (negative cause resulting in undesirable outcome)', 'Noun + の / Verb plain + せいで attributes blame to a cause for a bad result.') ON CONFLICT DO NOTHING;
INSERT INTO "GrammarPatternExercise" ("id", "level", "scenario", "sentence", "correctPattern", "options", "meaning", "explanation") VALUES ('gp-13', 'N3', 'Expressing that something happens every single time you hear a nostalgic song.', 'この曲を聴く___、故郷の家族を思い出します。', '〜たびに', '["〜たびに","〜うちに","〜最中に","〜途中で"]', 'Every time / Whenever X happens, Y always follows', 'Noun + の / Verb [Dictionary form] + たびに means ''every time X happens''.') ON CONFLICT DO NOTHING;
INSERT INTO "GrammarPatternExercise" ("id", "level", "scenario", "sentence", "correctPattern", "options", "meaning", "explanation") VALUES ('gp-14', 'N3', 'Urging someone to eat the warm ramen before it gets completely cold.', 'ラーメンが温かい___、早く召し上がってください。', '〜うちに', '["〜うちに","〜たびに","〜あまり","〜うえに"]', 'While / Before a state changes', 'Adjective / Verb [Dictionary or Continuous] + うちに means doing something while a favorable state lasts.') ON CONFLICT DO NOTHING;
INSERT INTO "KeigoExercise" ("id", "plain", "polite", "sonkeigo", "kenjougo", "meaning", "contextNote") VALUES ('k-1', '行く (iku)', '行きます', 'いらっしゃる / おいでになる', '参る (まいる) / 伺う (うかがう)', 'To go', 'Use いらっしゃる when the client/superior is going; use 参る or 伺う when you are going to their office.') ON CONFLICT DO NOTHING;
INSERT INTO "KeigoExercise" ("id", "plain", "polite", "sonkeigo", "kenjougo", "meaning", "contextNote") VALUES ('k-2', '来る (kuru)', '来ます', 'いらっしゃる / お見えになる / お越しになる', '参る (まいる)', 'To come', 'When welcoming a client: 『よくお越しくださいました』; when arriving: 『田中が参りました』.') ON CONFLICT DO NOTHING;
INSERT INTO "KeigoExercise" ("id", "plain", "polite", "sonkeigo", "kenjougo", "meaning", "contextNote") VALUES ('k-3', 'いる (iru)', 'います', 'いらっしゃる / おいでになる', 'おる', 'To be (animate/present)', 'Sonkeigo: 『社長はいらっしゃいますか』 vs Humble: 『はい、社内におります』.') ON CONFLICT DO NOTHING;
INSERT INTO "KeigoExercise" ("id", "plain", "polite", "sonkeigo", "kenjougo", "meaning", "contextNote") VALUES ('k-4', '言う (iu)', '言います', 'おっしゃる', '申す (もうす) / 申し上げる', 'To say / To tell', 'Customer says: 『お客様がおっしゃいました』 vs You introduce: 『田中と申します』.') ON CONFLICT DO NOTHING;
INSERT INTO "KeigoExercise" ("id", "plain", "polite", "sonkeigo", "kenjougo", "meaning", "contextNote") VALUES ('k-5', '食べる / 飲む (taberu / nomu)', '食べます / 飲みます', '召し上がる (めしあがる)', 'いただく / 頂戴する', 'To eat / To drink', 'Offer to guest: 『どうぞ召し上がってください』 vs Before receiving: 『いただきます』.') ON CONFLICT DO NOTHING;
INSERT INTO "KeigoExercise" ("id", "plain", "polite", "sonkeigo", "kenjougo", "meaning", "contextNote") VALUES ('k-6', '見る (miru)', '見ます', 'ご覧になる (ごらんになる)', '拝見する (はいけんする)', 'To see / To look at', 'Ask client to view: 『資料をご覧ください』 vs When checking client''s document: 『拝見します』.') ON CONFLICT DO NOTHING;
INSERT INTO "KeigoExercise" ("id", "plain", "polite", "sonkeigo", "kenjougo", "meaning", "contextNote") VALUES ('k-7', 'する (suru)', 'します', 'なさる / される', 'いたす', 'To do', 'Asking what boss will do: 『どうなさいますか』 vs Committing to help: 『私が手配いたします』.') ON CONFLICT DO NOTHING;
INSERT INTO "KeigoExercise" ("id", "plain", "polite", "sonkeigo", "kenjougo", "meaning", "contextNote") VALUES ('k-8', '知っている (shitte iru)', '知っています', 'ご存じです (ごぞんじです)', '存じております / 存じ上げております', 'To know', 'Ask client: 『その件をご存じですか』 vs Humble answer: 『はい、存じ上げております』.') ON CONFLICT DO NOTHING;
INSERT INTO "KeigoExercise" ("id", "plain", "polite", "sonkeigo", "kenjougo", "meaning", "contextNote") VALUES ('k-9', '聞く / 尋ねる / 訪ねる (kiku / tazuneru)', '聞きます / 尋ねます', 'お聞きになる', '伺う (うかがう) / 拝聴する', 'To ask / To inquire / To visit', 'When visiting client office: 『明日10時に伺います』; asking question: 『お話を伺いました』.') ON CONFLICT DO NOTHING;
INSERT INTO "KeigoExercise" ("id", "plain", "polite", "sonkeigo", "kenjougo", "meaning", "contextNote") VALUES ('k-10', '会う (au)', '会います', 'お会いになる', 'お目にかかる (おめにかかる)', 'To meet', 'Saying to a business partner: 『お目にかかれて光栄です』 (Honored to meet you).') ON CONFLICT DO NOTHING;
INSERT INTO "KeigoExercise" ("id", "plain", "polite", "sonkeigo", "kenjougo", "meaning", "contextNote") VALUES ('k-11', 'もらう (morau)', 'もらいます', 'お受け取りになる', 'いただく / 頂戴する (ちょうだいする)', 'To receive', 'When receiving a business card: 『お名刺を頂戴いたします』.') ON CONFLICT DO NOTHING;
INSERT INTO "KeigoExercise" ("id", "plain", "polite", "sonkeigo", "kenjougo", "meaning", "contextNote") VALUES ('k-12', 'あげる (ageru)', 'あげます', 'お与えになる', '差し上げる (さしあげる)', 'To give', 'Offering gift to client: 『ささやかですが、お土産を差し上げます』.') ON CONFLICT DO NOTHING;
INSERT INTO "KeigoExercise" ("id", "plain", "polite", "sonkeigo", "kenjougo", "meaning", "contextNote") VALUES ('k-13', 'わかる (wakaru)', 'わかります / わかりました', 'ご理解になる', 'かしこまりました / 承知いたしました', 'To understand / Acknowledge', 'Business acknowledgement standard: 『かしこまりました』 or 『承知いたしました』 (Never ''了解です'' to superiors).') ON CONFLICT DO NOTHING;
INSERT INTO "KeigoExercise" ("id", "plain", "polite", "sonkeigo", "kenjougo", "meaning", "contextNote") VALUES ('k-14', '着る (kiru)', '着ます', 'お召しになる (おめしになる)', '身につける / 着用する', 'To wear', 'Praising client outfit: 『素敵なコートをお召しですね』.') ON CONFLICT DO NOTHING;
INSERT INTO "DictationExercise" ("id", "audioPrompt", "japanese", "reading", "romaji", "translation", "level", "hint") VALUES ('d-1', 'おはようございます。きょうもがんばりましょう。', 'おはようございます。今日も頑張りましょう。', 'おはようございます。きょうもがんばりましょう。', 'ohayou gozaimasu. kyou mo ganbarimashou.', 'Good morning! Let''s do our best today too.', 'N5', 'Morning greeting and encouragement') ON CONFLICT DO NOTHING;
INSERT INTO "DictationExercise" ("id", "audioPrompt", "japanese", "reading", "romaji", "translation", "level", "hint") VALUES ('d-2', 'すみません、このえきからとうきょうタワーまでどういきますか。', 'すみません、この駅から東京タワーまでどう行きますか。', 'すみません、このえきからとうきょうたわーまでどういきますか。', 'sumimasen, kono eki kara toukyou tawaa made dou ikimasu ka.', 'Excuse me, how do I get to Tokyo Tower from this station?', 'N5', 'Asking for directions to a famous landmark') ON CONFLICT DO NOTHING;
INSERT INTO "DictationExercise" ("id", "audioPrompt", "japanese", "reading", "romaji", "translation", "level", "hint") VALUES ('d-3', 'わたしはまいにち、あさごはんをたべてからがっこうへいきます。', '私は毎日、朝ご飯を食べてから学校へ行きます。', 'わたしは まいにち、あさごはんを たべてから がっこうへ いきます。', 'watashi wa mainichi, asagohan o tabete kara gakkou e ikimasu.', 'Every day, I go to school after eating breakfast.', 'N5', 'Daily morning routine with 〜てから') ON CONFLICT DO NOTHING;
INSERT INTO "DictationExercise" ("id", "audioPrompt", "japanese", "reading", "romaji", "translation", "level", "hint") VALUES ('d-4', 'きのう、ともだちといっしょにおいしいラーメンをたべました。', '昨日、友達と一緒においしいラーメンを食べました。', 'きのう、ともだちと いっしょに おいしい らーめんを たべました。', 'kinou, tomodachi to issho ni oishii raamen o tabemashita.', 'Yesterday, I ate delicious ramen together with a friend.', 'N5', 'Past action with a friend') ON CONFLICT DO NOTHING;
INSERT INTO "DictationExercise" ("id", "audioPrompt", "japanese", "reading", "romaji", "translation", "level", "hint") VALUES ('d-5', 'すみません、メニューをみせてください。みずもおねがいします。', 'すみません、メニューを見せてください。水もお願いします。', 'すみません、めにゅーを みせてください。みずも おねがいします。', 'sumimasen, menyuu o misete kudasai. mizu mo onegaishimasu.', 'Excuse me, please show me the menu. Water as well, please.', 'N5', 'Polite request at a restaurant') ON CONFLICT DO NOTHING;
INSERT INTO "DictationExercise" ("id", "audioPrompt", "japanese", "reading", "romaji", "translation", "level", "hint") VALUES ('d-6', 'らいしゅうのしけんのために、まいばんふくしゅうしています。', '来週の試験のために、毎晩復習しています。', 'らいしゅうの しけんのために、まいばん ふくしゅう しています。', 'raishuu no shiken no tame ni, maiban fukushuu shiteimasu.', 'For next week''s exam, I review every night.', 'N4', 'Preparation for upcoming test (〜のために)') ON CONFLICT DO NOTHING;
INSERT INTO "DictationExercise" ("id", "audioPrompt", "japanese", "reading", "romaji", "translation", "level", "hint") VALUES ('d-7', 'てんきよほうによると、あしたはごごからあめがふるそうです。', '天気予報によると、明日は午後から雨が降るそうです。', 'てんきよほうによると、あしたは ごごから あめが ふるそうです。', 'tenki yohou ni yoru to, ashita wa gogo kara ame ga furu sou desu.', 'According to the weather forecast, it is said it will rain from tomorrow afternoon.', 'N4', 'Hearsay grammar (〜によると ... 〜そうだ)') ON CONFLICT DO NOTHING;
INSERT INTO "DictationExercise" ("id", "audioPrompt", "japanese", "reading", "romaji", "translation", "level", "hint") VALUES ('d-8', 'にほんごがもっとじょうずにすらすらはなせるようになりたいです。', '日本語がもっと上手にすらすら話せるようになりたいです。', 'にほんごが もっと じょうずに すらすら はなせるように なりたいです。', 'nihongo ga motto jouzu ni surasura hanaseru you ni naritai desu.', 'I want to become able to speak Japanese more fluently.', 'N4', 'Expressing a desired capability (〜ようになる)') ON CONFLICT DO NOTHING;
INSERT INTO "DictationExercise" ("id", "audioPrompt", "japanese", "reading", "romaji", "translation", "level", "hint") VALUES ('d-9', 'パスポートをなくしてしまったので、たいしかんへいかなければなりません。', 'パスポートをなくしてしまったので、大使館へ行かなければなりません。', 'ぱすぽーとを なくしてしまったので、たいしかんへ いかなければなりません。', 'pasupooto o nakushite shimatta node, taishikan e ikanakereba narimasen.', 'Because I lost my passport, I have to go to the embassy.', 'N4', 'Regret (〜てしまう) and obligation (〜なければならない)') ON CONFLICT DO NOTHING;
INSERT INTO "DictationExercise" ("id", "audioPrompt", "japanese", "reading", "romaji", "translation", "level", "hint") VALUES ('d-10', 'しゅくだいをおわらせてから、ゲームをしてあそびました。', '宿題を終わらせてから、ゲームをして遊びました。', 'しゅくだいを おわらせてから、げーむをして あそびました。', 'shukudai o owarasete kara, geemu o shite asobimashita.', 'After finishing my homework, I played games and had fun.', 'N4', 'Sequential actions with transitive verb') ON CONFLICT DO NOTHING;
INSERT INTO "DictationExercise" ("id", "audioPrompt", "japanese", "reading", "romaji", "translation", "level", "hint") VALUES ('d-11', '健康のために毎日一万歩歩くことにしています。', '健康のために毎日一万歩歩くことにしています。', 'けんこうのために まいにち いちまんぽ あるくことに しています。', 'kenkou no tame ni mainichi ichimanpo aruku koto ni shiteimasu.', 'For my health, I make it a habit to walk 10,000 steps every day.', 'N3', 'Habitual rule (〜ことにしている)') ON CONFLICT DO NOTHING;
INSERT INTO "DictationExercise" ("id", "audioPrompt", "japanese", "reading", "romaji", "translation", "level", "hint") VALUES ('d-12', 'どんなに忙しくても、睡眠時間だけはしっかり確保するべきです。', 'どんなに忙しくても、睡眠時間だけはしっかり確保するべきです。', 'どんなに いそがしくても、すいみんじかん だけは しっかり かくほするべきです。', 'donna ni isogashikutemo, suimin jikan dake wa shikkari kakuho suru beki desu.', 'No matter how busy you are, you should secure adequate sleep time.', 'N3', 'No matter how (どんなに〜ても) + obligation (〜べき)') ON CONFLICT DO NOTHING;
INSERT INTO "DictationExercise" ("id", "audioPrompt", "japanese", "reading", "romaji", "translation", "level", "hint") VALUES ('d-13', '先輩のアドバイスのおかげで、無事にプロジェクトを完了できました。', '先輩のアドバイスのおかげで、無事にプロジェクトを完了できました。', 'せんぱいの あどばいすの おかげで、ぶじに ぷろじぇくとを かんりょう できました。', 'senpai no adobaisu no okage de, buji ni purojekuto o kanryou dekimashita.', 'Thanks to my senior''s advice, we were able to complete the project smoothly.', 'N3', 'Gratitude expression (〜のおかげで)') ON CONFLICT DO NOTHING;
INSERT INTO "ShadowingExercise" ("id", "title", "level", "theme", "description", "lines") VALUES ('sh-1', 'Self Introduction at Work', 'N5', 'Business Greeting', 'Learn polite introductory Japanese for greeting coworkers and introducing your background.', '[{"speaker":"Tanaka","japanese":"はじめまして。田中と申します。","reading":"はじめまして。たなかと もうします。","english":"Nice to meet you. My name is Tanaka."},{"speaker":"Tanaka","japanese":"今年からこちらの部署で働くことになりました。","reading":"ことしから こちらの ぶしょで はたらくことに なりました。","english":"I will be working in this department starting this year."},{"speaker":"Tanaka","japanese":"至らない点も多いと思いますが、一生懸命頑張ります。","reading":"いたらない てんも おおいと おもいますが、いっしょうけんめい がんばります。","english":"I still have much to learn, but I will do my absolute best."},{"speaker":"Tanaka","japanese":"どうぞよろしくお願いいたします。","reading":"どうぞ よろしく おねがいいたします。","english":"I look forward to working with you all."}]') ON CONFLICT DO NOTHING;
INSERT INTO "ShadowingExercise" ("id", "title", "level", "theme", "description", "lines") VALUES ('sh-2', 'Ordering at a Traditional Cafe', 'N5', 'Daily Life & Dining', 'Practice smooth conversational rhythm when entering a coffee shop, requesting a seat, and ordering.', '[{"speaker":"Staff","japanese":"いらっしゃいませ。何名様でしょうか。","reading":"いらっしゃいませ。なんめいさま でしょうか。","english":"Welcome! How many people in your party?"},{"speaker":"Customer","japanese":"一人です。窓側の席は空いていますか。","reading":"ひとりです。まどがわの せきは あいていますか。","english":"Just one. Is a window seat available?"},{"speaker":"Staff","japanese":"はい、どうぞこちらの席へご案内いたします。","reading":"はい、どうぞ こちらの せきへ ごあんない いたします。","english":"Yes, please allow me to show you to this table."},{"speaker":"Customer","japanese":"アイスコーヒーと抹茶ケーキをお願いします。","reading":"あいすこーひーと まっちゃけーきを おねがいします。","english":"An iced coffee and matcha cake, please."},{"speaker":"Staff","japanese":"かしこまりました。少々お待ちくださいませ。","reading":"かしこまりました。しょうしょう おまち くださいませ。","english":"Understood right away. Please wait just a moment."}]') ON CONFLICT DO NOTHING;
INSERT INTO "ShadowingExercise" ("id", "title", "level", "theme", "description", "lines") VALUES ('sh-3', 'Asking Directions in Shinjuku', 'N4', 'Travel & Transit', 'Navigate Japanese train stations and ask friendly locals for walking directions.', '[{"speaker":"Traveler","japanese":"すみません、ちょっとお聞きしてもよろしいですか。","reading":"すみません、ちょっと おききしても よろしいですか。","english":"Excuse me, may I ask you a quick question?"},{"speaker":"Local","japanese":"はい、何でしょうか。道に迷われましたか。","reading":"はい、なんでしょうか。みちに まよわれましたか。","english":"Yes, what is it? Are you lost?"},{"speaker":"Traveler","japanese":"東京都庁に行きたいのですが、どの出口を出ればいいですか。","reading":"とうきょうとちょうに いきたいのですが、どのでぐちを でれば いいですか。","english":"I want to go to the Tokyo Metropolitan Government Building. Which exit should I take?"},{"speaker":"Local","japanese":"西口を出て、地下通路をまっすぐ５分ほど歩くと着きますよ。","reading":"にしぐちを でて、ちかつうろを まっすぐ ごふんほど あるくと つきますよ。","english":"Take the West Exit, walk straight through the underground passage for about 5 minutes, and you''ll arrive."},{"speaker":"Traveler","japanese":"分かりやすく教えていただき、ありがとうございます！","reading":"わかりやすく おしえていただき、ありがとう ございます！","english":"Thank you very much for the clear explanation!"}]') ON CONFLICT DO NOTHING;
INSERT INTO "ShadowingExercise" ("id", "title", "level", "theme", "description", "lines") VALUES ('sh-4', 'Checking into a Kyoto Ryokan', 'N4', 'Hospitality & Travel', 'Master polite hotel Japanese when confirming reservations and asking about hot springs and dining.', '[{"speaker":"Guest","japanese":"こんばんは。本日予約しているスミスと申します。","reading":"こんばんは。ほんじつ よやくしている すみすと もうします。","english":"Good evening. My name is Smith, I have a reservation for today."},{"speaker":"Staff","japanese":"スミス様、ようこそお越しくださいました。お部屋をご用意しております。","reading":"すみすさま、ようこそ おこしくださいました。おへやを ごようい しております。","english":"Mr. Smith, welcome! We have your traditional room prepared."},{"speaker":"Guest","japanese":"温泉は何時から利用できますか。","reading":"おんせんは なんじから りよう できますか。","english":"From what time can we use the hot spring bath?"},{"speaker":"Staff","japanese":"大浴場は夜通しご利用いただけます。夕食は七時にお部屋へお持ちします。","reading":"だいよくじょうは よどおし ごりよう いただけます。ゆうしょくは しちじに おへやへ おもちします。","english":"The main bath is available all night. Dinner will be served to your room at 7:00 PM."}]') ON CONFLICT DO NOTHING;
INSERT INTO "ShadowingExercise" ("id", "title", "level", "theme", "description", "lines") VALUES ('sh-5', 'Discussing Weekend Plans with a Colleague', 'N3', 'Casual Business & Social', 'Natural conversational transitions, giving recommendations, and making plans with peers.', '[{"speaker":"Kenji","japanese":"今度の週末、何か予定ある？もしよかったらハイキングに行かない？","reading":"こんどの しゅうまつ、なにか よてい ある？もし よかったら はいきんぐに いかない？","english":"Do you have any plans this upcoming weekend? If you''d like, want to go hiking?"},{"speaker":"Yuki","japanese":"いいね！高尾山あたりはどう？紅葉が見頃らしいよ。","reading":"いいね！たかおさん あたりは どう？こうようが みごろ らしいよ。","english":"Sounds great! How about around Mt. Takao? I heard the autumn leaves are at their peak."},{"speaker":"Kenji","japanese":"最高だね。朝早く出発すれば混雑を避けられると思うんだ。","reading":"さいこうだね。あさはやく しゅっぱつ すれば こんざつを さけられると おもうんだ。","english":"Awesome. If we leave early in the morning, I think we can beat the crowds."},{"speaker":"Yuki","japanese":"賛成！じゃあ新宿駅に朝七時半集合にしようか。","reading":"さんせい！じゃあ しんじゅくえきに あさ しちじはんに しゅうごうに しようか。","english":"Agreed! Let''s meet at Shinjuku Station at 7:30 AM then."}]') ON CONFLICT DO NOTHING;
INSERT INTO "WordPair" ("id", "pairType", "themeCategory", "wordA", "wordB", "relationLabel", "level") VALUES ('pair-1', 'antonym', NULL, '{"kanji":"大きい","reading":"おおきい","romaji":"ookii","meaning":"Big / Large"}', '{"kanji":"小さい","reading":"ちいさい","romaji":"chiisai","meaning":"Small / Little"}', 'Opposites (Antonyms)', 'N5') ON CONFLICT DO NOTHING;
INSERT INTO "WordPair" ("id", "pairType", "themeCategory", "wordA", "wordB", "relationLabel", "level") VALUES ('pair-2', 'antonym', NULL, '{"kanji":"高い","reading":"たかい","romaji":"takai","meaning":"Expensive / High"}', '{"kanji":"安い","reading":"やすい","romaji":"yasui","meaning":"Cheap / Inexpensive"}', 'Opposites (Antonyms)', 'N5') ON CONFLICT DO NOTHING;
INSERT INTO "WordPair" ("id", "pairType", "themeCategory", "wordA", "wordB", "relationLabel", "level") VALUES ('pair-3', 'antonym', NULL, '{"kanji":"暑い","reading":"あつい","romaji":"atsui","meaning":"Hot (Weather)"}', '{"kanji":"寒い","reading":"さむい","romaji":"samui","meaning":"Cold (Weather)"}', 'Opposites (Antonyms)', 'N5') ON CONFLICT DO NOTHING;
INSERT INTO "WordPair" ("id", "pairType", "themeCategory", "wordA", "wordB", "relationLabel", "level") VALUES ('pair-4', 'antonym', NULL, '{"kanji":"行く","reading":"いく","romaji":"iku","meaning":"To go"}', '{"kanji":"来る","reading":"くる","romaji":"kuru","meaning":"To come"}', 'Opposites (Antonyms)', 'N5') ON CONFLICT DO NOTHING;
INSERT INTO "WordPair" ("id", "pairType", "themeCategory", "wordA", "wordB", "relationLabel", "level") VALUES ('pair-5', 'antonym', NULL, '{"kanji":"買う","reading":"かう","romaji":"kau","meaning":"To buy"}', '{"kanji":"売る","reading":"うる","romaji":"uru","meaning":"To sell"}', 'Opposites (Antonyms)', 'N5') ON CONFLICT DO NOTHING;
INSERT INTO "WordPair" ("id", "pairType", "themeCategory", "wordA", "wordB", "relationLabel", "level") VALUES ('pair-6', 'antonym', NULL, '{"kanji":"上","reading":"うえ","romaji":"ue","meaning":"Above / Top"}', '{"kanji":"下","reading":"した","romaji":"shita","meaning":"Below / Under"}', 'Opposites (Antonyms)', 'N5') ON CONFLICT DO NOTHING;
INSERT INTO "WordPair" ("id", "pairType", "themeCategory", "wordA", "wordB", "relationLabel", "level") VALUES ('pair-7', 'antonym', NULL, '{"kanji":"前","reading":"まえ","romaji":"mae","meaning":"Front / Before"}', '{"kanji":"後ろ","reading":"うしろ","romaji":"ushiro","meaning":"Back / Behind"}', 'Opposites (Antonyms)', 'N5') ON CONFLICT DO NOTHING;
INSERT INTO "WordPair" ("id", "pairType", "themeCategory", "wordA", "wordB", "relationLabel", "level") VALUES ('pair-8', 'antonym', NULL, '{"kanji":"始める","reading":"はじめる","romaji":"hajimeru","meaning":"To begin / start"}', '{"kanji":"終わる","reading":"おわる","romaji":"owaru","meaning":"To end / finish"}', 'Opposites (Antonyms)', 'N4') ON CONFLICT DO NOTHING;
INSERT INTO "WordPair" ("id", "pairType", "themeCategory", "wordA", "wordB", "relationLabel", "level") VALUES ('pair-9', 'antonym', NULL, '{"kanji":"強い","reading":"つよい","romaji":"tsuyoi","meaning":"Strong / Powerful"}', '{"kanji":"弱い","reading":"よわい","romaji":"yowai","meaning":"Weak / Fragile"}', 'Opposites (Antonyms)', 'N4') ON CONFLICT DO NOTHING;
INSERT INTO "WordPair" ("id", "pairType", "themeCategory", "wordA", "wordB", "relationLabel", "level") VALUES ('pair-10', 'antonym', NULL, '{"kanji":"開ける","reading":"あける","romaji":"akeru","meaning":"To open"}', '{"kanji":"閉める","reading":"しめる","romaji":"shimeru","meaning":"To close"}', 'Opposites (Antonyms)', 'N4') ON CONFLICT DO NOTHING;
INSERT INTO "WordPair" ("id", "pairType", "themeCategory", "wordA", "wordB", "relationLabel", "level") VALUES ('pair-11', 'antonym', NULL, '{"kanji":"成功","reading":"せいこう","romaji":"seikou","meaning":"Success"}', '{"kanji":"失敗","reading":"しっぱい","romaji":"shippai","meaning":"Failure"}', 'Opposites (Antonyms)', 'N3') ON CONFLICT DO NOTHING;
INSERT INTO "WordPair" ("id", "pairType", "themeCategory", "wordA", "wordB", "relationLabel", "level") VALUES ('pair-12', 'antonym', NULL, '{"kanji":"増加","reading":"ぞうか","romaji":"zouka","meaning":"Increase / Growth"}', '{"kanji":"減少","reading":"げんしょう","romaji":"genshou","meaning":"Decrease / Reduction"}', 'Opposites (Antonyms)', 'N3') ON CONFLICT DO NOTHING;
INSERT INTO "WordPair" ("id", "pairType", "themeCategory", "wordA", "wordB", "relationLabel", "level") VALUES ('syn-1', 'synonym', NULL, '{"kanji":"綺麗","reading":"きれい","romaji":"kirei","meaning":"Pretty / Clean"}', '{"kanji":"美しい","reading":"うつくしい","romaji":"utsukushii","meaning":"Beautiful"}', 'Similar Meaning (Synonyms)', 'N5') ON CONFLICT DO NOTHING;
INSERT INTO "WordPair" ("id", "pairType", "themeCategory", "wordA", "wordB", "relationLabel", "level") VALUES ('syn-2', 'synonym', NULL, '{"kanji":"大切","reading":"たいせつ","romaji":"taisetsu","meaning":"Important / Precious"}', '{"kanji":"大事","reading":"だいじ","romaji":"daiji","meaning":"Important / Serious"}', 'Similar Meaning (Synonyms)', 'N4') ON CONFLICT DO NOTHING;
INSERT INTO "WordPair" ("id", "pairType", "themeCategory", "wordA", "wordB", "relationLabel", "level") VALUES ('syn-3', 'synonym', NULL, '{"kanji":"急に","reading":"きゅうに","romaji":"kyuuni","meaning":"Suddenly / Abruptly"}', '{"kanji":"突然","reading":"とつぜん","romaji":"totsuzen","meaning":"Suddenly / Unexpectedly"}', 'Similar Meaning (Synonyms)', 'N4') ON CONFLICT DO NOTHING;
INSERT INTO "FuriganaPassage" ("id", "level", "title", "category", "readTime", "summary", "sentences", "comprehensionQuestions") VALUES ('furi-1', 'N5', '週末の散歩 (Weekend Walk)', 'Daily Life', '2 min', 'A peaceful Saturday walk through the neighbourhood park and local bakery.', '[{"id":"s1","japanese":"土曜日の朝、公園へ散歩に行きました。","translation":"On Saturday morning, I went for a walk to the park.","tokens":[{"surface":"土曜日","reading":"どようび","isKanji":true,"meaning":"Saturday"},{"surface":"の"},{"surface":"朝","reading":"あさ","isKanji":true,"meaning":"Morning"},{"surface":"、"},{"surface":"公園","reading":"こうえん","isKanji":true,"meaning":"Park"},{"surface":"へ"},{"surface":"散歩","reading":"さんぽ","isKanji":true,"meaning":"Stroll / Walk"},{"surface":"に"},{"surface":"行き","reading":"いき","isKanji":true,"meaning":"To go"},{"surface":"ました。"}]},{"id":"s2","japanese":"天気はとても良くて、空が青かったです。","translation":"The weather was very nice, and the sky was blue.","tokens":[{"surface":"天気","reading":"てんき","isKanji":true,"meaning":"Weather"},{"surface":"はとても"},{"surface":"良く","reading":"よく","isKanji":true,"meaning":"Good / Nice"},{"surface":"て、"},{"surface":"空","reading":"そら","isKanji":true,"meaning":"Sky"},{"surface":"が"},{"surface":"青かった","reading":"あおかった","isKanji":true,"meaning":"Was blue"},{"surface":"です。"}]},{"id":"s3","japanese":"公園の木の下で、白い猫を見ました。","translation":"Under a tree in the park, I saw a white cat.","tokens":[{"surface":"公園","reading":"こうえん","isKanji":true,"meaning":"Park"},{"surface":"の"},{"surface":"木","reading":"き","isKanji":true,"meaning":"Tree"},{"surface":"の"},{"surface":"下","reading":"した","isKanji":true,"meaning":"Under"},{"surface":"で、"},{"surface":"白い","reading":"しろい","isKanji":true,"meaning":"White"},{"surface":"猫","reading":"ねこ","isKanji":true,"meaning":"Cat"},{"surface":"を"},{"surface":"見","reading":"み","isKanji":true,"meaning":"To see"},{"surface":"ました。"}]},{"id":"s4","japanese":"帰り道に美味しいパンを買って、家で食べました。","translation":"On the way home, I bought delicious bread and ate it at home.","tokens":[{"surface":"帰り道","reading":"かえりみち","isKanji":true,"meaning":"Way back home"},{"surface":"に"},{"surface":"美味しい","reading":"おいしい","isKanji":true,"meaning":"Delicious"},{"surface":"パンを"},{"surface":"買って","reading":"かって","isKanji":true,"meaning":"Bought (te-form)"},{"surface":"、"},{"surface":"家","reading":"いえ","isKanji":true,"meaning":"House / Home"},{"surface":"で"},{"surface":"食べ","reading":"たべ","isKanji":true,"meaning":"Ate"},{"surface":"ました。"}]}]', '[{"question":"木の下で何を見ましたか？ (What was seen under the tree?)","options":["白い犬 (White dog)","白い猫 (White cat)","黒い鳥 (Black bird)","小さい花 (Small flower)"],"correctIndex":1,"explanation":"The passage mentions: 「公園の木の下で、白い猫を見ました。」"},{"question":"帰り道に何を買いましたか？ (What was bought on the way home?)","options":["お茶 (Tea)","ケーキ (Cake)","パン (Bread)","本 (Book)"],"correctIndex":2,"explanation":"The text says: 「帰り道に美味しいパンを買って...」"}]') ON CONFLICT DO NOTHING;
INSERT INTO "FuriganaPassage" ("id", "level", "title", "category", "readTime", "summary", "sentences", "comprehensionQuestions") VALUES ('furi-2', 'N4', '駅前の新しい図書館 (The New Library by the Station)', 'Community', '3 min', 'Discovering modern reading rooms, digital archives, and a rooftop garden at the city library.', '[{"id":"s1","japanese":"先週、駅の前に新しい市立図書館が開館しました。","translation":"Last week, a new municipal library opened in front of the station.","tokens":[{"surface":"先週","reading":"せんしゅう","isKanji":true,"meaning":"Last week"},{"surface":"、"},{"surface":"駅","reading":"えき","isKanji":true,"meaning":"Station"},{"surface":"の"},{"surface":"前","reading":"まえ","isKanji":true,"meaning":"Front"},{"surface":"に"},{"surface":"新しい","reading":"あたらしい","isKanji":true,"meaning":"New"},{"surface":"市立図書館","reading":"しりつとしょかん","isKanji":true,"meaning":"City library"},{"surface":"が"},{"surface":"開館","reading":"かいかん","isKanji":true,"meaning":"Opening of a building/hall"},{"surface":"しました。"}]},{"id":"s2","japanese":"建物の中は広くて明るく、たくさんの学習机があります。","translation":"The interior of the building is spacious and bright, with many study desks.","tokens":[{"surface":"建物","reading":"たてもの","isKanji":true,"meaning":"Building"},{"surface":"の"},{"surface":"中","reading":"なか","isKanji":true,"meaning":"Inside"},{"surface":"は"},{"surface":"広く","reading":"ひろく","isKanji":true,"meaning":"Spacious / Wide"},{"surface":"て"},{"surface":"明るく","reading":"あかるく","isKanji":true,"meaning":"Bright"},{"surface":"、たくさんの"},{"surface":"学習机","reading":"がくしゅうづくえ","isKanji":true,"meaning":"Study desks"},{"surface":"が"},{"surface":"あります。"}]},{"id":"s3","japanese":"屋上には緑豊かな庭園があり、富士山を眺めることができます。","translation":"On the rooftop there is a lush green garden where you can view Mount Fuji.","tokens":[{"surface":"屋上","reading":"おくじょう","isKanji":true,"meaning":"Rooftop"},{"surface":"には"},{"surface":"緑豊か","reading":"みどりゆたか","isKanji":true,"meaning":"Lush green"},{"surface":"な"},{"surface":"庭園","reading":"ていえん","isKanji":true,"meaning":"Garden"},{"surface":"があり、"},{"surface":"富士山","reading":"ふじさん","isKanji":true,"meaning":"Mount Fuji"},{"surface":"を"},{"surface":"眺める","reading":"ながめる","isKanji":true,"meaning":"To gaze at / view"},{"surface":"ことができます。"}]}]', '[{"question":"屋上で何ができますか？ (What can you do on the rooftop?)","options":["本を借りる (Borrow books)","富士山を眺める (View Mt. Fuji)","コーヒーを飲む (Drink coffee)","寝る (Sleep)"],"correctIndex":1,"explanation":"「屋上には緑豊かな庭園があり、富士山を眺めることができます。」"}]') ON CONFLICT DO NOTHING;
INSERT INTO "FuriganaPassage" ("id", "level", "title", "category", "readTime", "summary", "sentences", "comprehensionQuestions") VALUES ('furi-3', 'N3', '伝統工芸と現代デザイン (Traditional Crafts & Modern Design)', 'Culture', '3.5 min', 'How young artisans in Kyoto are blending Edo-era ceramics with contemporary tableware.', '[{"id":"s1","japanese":"京都の工房では、若い職人たちが伝統的な陶芸技術を継承しています。","translation":"In workshops in Kyoto, young artisans are carrying on traditional ceramic techniques.","tokens":[{"surface":"京都","reading":"きょうと","isKanji":true,"meaning":"Kyoto"},{"surface":"の"},{"surface":"工房","reading":"こうぼう","isKanji":true,"meaning":"Workshop"},{"surface":"では、"},{"surface":"若い","reading":"わかい","isKanji":true,"meaning":"Young"},{"surface":"職人","reading":"しょくにん","isKanji":true,"meaning":"Artisan / Craftsman"},{"surface":"たちが"},{"surface":"伝統的","reading":"でんとうてき","isKanji":true,"meaning":"Traditional"},{"surface":"な"},{"surface":"陶芸","reading":"とうげい","isKanji":true,"meaning":"Ceramics / Pottery"},{"surface":"技術","reading":"ぎじゅつ","isKanji":true,"meaning":"Technique / Skill"},{"surface":"を"},{"surface":"継承","reading":"けいしょう","isKanji":true,"meaning":"Inheriting / Carrying on"},{"surface":"しています。"}]},{"id":"s2","japanese":"彼らは古い技法を守りながら、現代の生活に合った新しい器を創り出しています。","translation":"While preserving old methods, they create new tableware suited to modern living.","tokens":[{"surface":"彼ら","reading":"かれら","isKanji":true,"meaning":"They"},{"surface":"は"},{"surface":"古い","reading":"ふるい","isKanji":true,"meaning":"Old"},{"surface":"技法","reading":"ぎほう","isKanji":true,"meaning":"Method / Technique"},{"surface":"を"},{"surface":"守り","reading":"まもり","isKanji":true,"meaning":"Protecting"},{"surface":"ながら、"},{"surface":"現代","reading":"げんだい","isKanji":true,"meaning":"Modern era"},{"surface":"の"},{"surface":"生活","reading":"せいかつ","isKanji":true,"meaning":"Life / Living"},{"surface":"に"},{"surface":"合った","reading":"あった","isKanji":true,"meaning":"Fitting / Suited"},{"surface":"新しい","reading":"あたらしい","isKanji":true,"meaning":"New"},{"surface":"器","reading":"うつわ","isKanji":true,"meaning":"Vessel / Tableware"},{"surface":"を"},{"surface":"創り出して","reading":"つくりだして","isKanji":true,"meaning":"Creating"},{"surface":"います。"}]}]', '[{"question":"若い職人たちは何をしていますか？ (What are the young artisans doing?)","options":["海外に移住している (Migrating abroad)","伝統技術を継承しながら現代に合った器を創っている (Creating modern tableware while keeping traditional craft)","陶芸を辞めてデジタルアートを始めている (Quitting ceramics to start digital art)","古い器だけを集めて展示している (Only collecting and exhibiting antique wares)"],"correctIndex":1,"explanation":"彼らは伝統的な陶芸技術を継承しながら、現代の生活に合った新しい器を創り出しています。"}]') ON CONFLICT DO NOTHING;
INSERT INTO "KanjiContextSnippet" ("id", "level", "domain", "domainEmoji", "scenarioTitle", "snippetText", "targetKanji", "targetReading", "targetMeaning", "kanjiBreakdown", "contextQuestion", "readingQuestion") VALUES ('kc-1', 'N5', 'Transit', '🚆', 'Train Platform Announcement Board', 'まもなく ２番線に 各駅停車 新宿行きが まいります。黄色い線の 内側へ お下がりください。', '各駅停車', 'かくえきていしゃ', 'Local train (train stopping at every single station)', '[{"char":"各","onyomi":"カク","kunyomi":"おのおの","meaning":"Each / Every"},{"char":"駅","onyomi":"エキ","kunyomi":"-","meaning":"Station"},{"char":"停","onyomi":"テイ","kunyomi":"と・まる","meaning":"Halt / Stop"},{"char":"車","onyomi":"シャ","kunyomi":"くるま","meaning":"Car / Vehicle"}]', '{"prompt":"What type of train service is indicated by 「各駅停車」?","options":["Express train that skips minor stations","Local train that stops at every station on the line","Non-stop airport direct shuttle","Freight train not carrying passengers"],"correctIndex":1,"explanation":"「各」(each) + 「駅」(station) + 「停車」(stopping vehicle) means a local train that stops at every single station along the route."}', '{"prompt":"What is the correct reading of 「各駅停車」?","options":["かくえきていしゃ","おのおのえきどまり","かっこくしゃてい","かくえきとまり"],"correctIndex":0,"explanation":"The On''yomi compound is pronounced 「かくえきていしゃ」 (kaku-eki-tei-sha)."}') ON CONFLICT DO NOTHING;
INSERT INTO "KanjiContextSnippet" ("id", "level", "domain", "domainEmoji", "scenarioTitle", "snippetText", "targetKanji", "targetReading", "targetMeaning", "kanjiBreakdown", "contextQuestion", "readingQuestion") VALUES ('kc-2', 'N5', 'Shopping & Food', '🍜', 'Ramen Shop Entrance Door Notice', '【営業案内】本日の 営業時間 は 11:30〜21:00 です。毎週水曜日は 定休日 となっております。', '定休日', 'ていきゅうび', 'Regular scheduled holiday / Closed day', '[{"char":"定","onyomi":"テイ / ジョウ","kunyomi":"さだ・める","meaning":"Fixed / Regular"},{"char":"休","onyomi":"キュウ","kunyomi":"やす・む","meaning":"Rest / Holiday"},{"char":"日","onyomi":"ニチ / ジツ","kunyomi":"ひ / か","meaning":"Day / Sun"}]', '{"prompt":"If a shop sign states 「水曜日は 定休日」, what does it mean?","options":["The shop offers discount prices on Wednesday","Wednesday is the shop''s regular closed holiday","The shop is open 24 hours on Wednesday","Reservations are strictly mandatory on Wednesday"],"correctIndex":1,"explanation":"「定」(fixed) + 「休」(rest) + 「日」(day) = regular fixed day off or closed day."}', '{"prompt":"What is the correct reading of 「定休日」?","options":["ていきゅうび","じょうやすみひ","さだめやすみ","ていやすみび"],"correctIndex":0,"explanation":"The standard On''yomi reading is 「ていきゅうび」 (tei-kyuu-bi)."}') ON CONFLICT DO NOTHING;
INSERT INTO "KanjiContextSnippet" ("id", "level", "domain", "domainEmoji", "scenarioTitle", "snippetText", "targetKanji", "targetReading", "targetMeaning", "kanjiBreakdown", "contextQuestion", "readingQuestion") VALUES ('kc-3', 'N5', 'Public Notice', '🚪', 'Emergency Exit Sign in Public Hall', '火災や 地震の際は、落ち着いて 非常口 の緑色の 誘導灯に 従ってください。', '非常口', 'ひじょうぐち', 'Emergency Exit', '[{"char":"非","onyomi":"ヒ","kunyomi":"あら・ず","meaning":"Non / Unusual / Emergency"},{"char":"常","onyomi":"ジョウ","kunyomi":"つね","meaning":"Normal / Usual"},{"char":"口","onyomi":"コウ / ク","kunyomi":"くち","meaning":"Mouth / Opening / Exit"}]', '{"prompt":"Where should you evacuate through during an emergency according to this sign?","options":["The kitchen entrance","The green emergency exit (非常口)","The main elevator shaft","The rooftop helipad"],"correctIndex":1,"explanation":"「非常」(unusual / emergency) + 「口」(opening/exit) = Emergency Exit door."}', '{"prompt":"What is the correct reading of 「非常口」?","options":["ひじょうぐち","ひつねぐち","いじょうくち","ひじょうこう"],"correctIndex":0,"explanation":"It is read as 「ひじょうぐち」 (hi-jou-guchi) with rendaku voicing on くち -> ぐち."}') ON CONFLICT DO NOTHING;
INSERT INTO "KanjiContextSnippet" ("id", "level", "domain", "domainEmoji", "scenarioTitle", "snippetText", "targetKanji", "targetReading", "targetMeaning", "kanjiBreakdown", "contextQuestion", "readingQuestion") VALUES ('kc-4', 'N4', 'Transit', '🎫', 'IC Card Automated Gate Sign', '残額不足 の場合は、改札機の手前にある 自動精算機 でチャージを行ってください。', '自動精算機', 'じどうせいさんき', 'Automatic Fare Adjustment Machine', '[{"char":"自","onyomi":"ジ / シ","kunyomi":"みずか・ら","meaning":"Self / Auto"},{"char":"動","onyomi":"ドウ","kunyomi":"うご・く","meaning":"Move"},{"char":"精","onyomi":"セイ / ショウ","kunyomi":"-","meaning":"Refined / Exact"},{"char":"算","onyomi":"サン","kunyomi":"-","meaning":"Calculate / Settle"},{"char":"機","onyomi":"キ","kunyomi":"はた","meaning":"Machine / Mechanism"}]', '{"prompt":"When would a passenger use the 「自動精算機」 at a train station?","options":["To purchase a souvenir or snack","To adjust their fare / top up card when their balance is insufficient to exit","To request a train delay certificate from the conductor","To book a hotel near the station"],"correctIndex":1,"explanation":"「精算」(fare calculation / settlement) + 「機」(machine) is used when the IC card has insufficient balance (残額不足) to clear the gates."}', '{"prompt":"What is the reading of 「自動精算機」?","options":["じどうせいさんき","じどうけいさんき","みずからうごきはた","じどうしょうさんき"],"correctIndex":0,"explanation":"The reading is 「じどうせいさんき」 (ji-dou-sei-san-ki)."}') ON CONFLICT DO NOTHING;
INSERT INTO "KanjiContextSnippet" ("id", "level", "domain", "domainEmoji", "scenarioTitle", "snippetText", "targetKanji", "targetReading", "targetMeaning", "kanjiBreakdown", "contextQuestion", "readingQuestion") VALUES ('kc-5', 'N4', 'Shopping & Food', '🛒', 'Supermarket Fresh Produce Section', '本日入荷！ 地元農家より 直送 された 朝採れ 新鮮 な 有機野菜 コーナーです。', '新鮮', 'しんせん', 'Fresh / Vibrant', '[{"char":"新","onyomi":"シン","kunyomi":"あたら・しい","meaning":"New / Fresh"},{"char":"鮮","onyomi":"セン","kunyomi":"あざ・やか","meaning":"Vivid / Fresh"}]', '{"prompt":"How are the vegetables described by the word 「新鮮」?","options":["Frozen and imported from overseas","Fresh and recently harvested","Processed and canned","Discounted due to expiration"],"correctIndex":1,"explanation":"「新」(new) + 「鮮」(vivid/fresh) describes freshly harvested, high-quality produce."}', '{"prompt":"What is the correct reading of 「新鮮」?","options":["しんせん","あたらあざやか","にいせん","しんぜん"],"correctIndex":0,"explanation":"The standard On''yomi reading is 「しんせん」 (shin-sen)."}') ON CONFLICT DO NOTHING;
INSERT INTO "KanjiContextSnippet" ("id", "level", "domain", "domainEmoji", "scenarioTitle", "snippetText", "targetKanji", "targetReading", "targetMeaning", "kanjiBreakdown", "contextQuestion", "readingQuestion") VALUES ('kc-6', 'N3', 'Weather & Safety', '⚠️', 'Meteorological Agency Disaster Advisory', '大型で非常に強い 台風 の接近に伴い、大雨警報 と 暴風警報 が発令されました。', '警報', 'けいほう', 'Emergency Warning / Severe Weather Alert', '[{"char":"警","onyomi":"ケイ","kunyomi":"いまし・める","meaning":"Admonish / Guard / Warn"},{"char":"報","onyomi":"ホウ","kunyomi":"むく・いる","meaning":"Report / News / Information"}]', '{"prompt":"What does the announcement 「大雨警報」 signify?","options":["A light pleasant drizzle forecast for tomorrow","An official emergency severe heavy rain warning","A heat wave advisory","A recommendation to plant rain crops"],"correctIndex":1,"explanation":"「警」(warn) + 「報」(report) = official critical warning alert issued during hazardous weather conditions."}', '{"prompt":"What is the correct reading of 「警報」?","options":["けいほう","けいぽう","けいこく","きょうほう"],"correctIndex":0,"explanation":"The standard On''yomi reading is 「けいほう」 (kei-hou)."}') ON CONFLICT DO NOTHING;
INSERT INTO "GrammarLesson" ("id", "level", "title", "meaning", "structure", "examples") VALUES ('n5_g001', 'N5', '〜は〜です', 'A is B (equational statement)', 'Noun は Noun です', '[{"japanese":"私は学生です。","reading":"わたしはがくせいです。","english":"I am a student."},{"japanese":"これは本です。","reading":"これはほんです。","english":"This is a book."}]') ON CONFLICT DO NOTHING;
INSERT INTO "GrammarLesson" ("id", "level", "title", "meaning", "structure", "examples") VALUES ('n5_g002', 'N5', '〜じゃないです / 〜ではありません', 'A is not B (negative equational)', 'Noun じゃないです / Noun ではありません', '[{"japanese":"私は先生じゃないです。","reading":"わたしはせんせいじゃないです。","english":"I am not a teacher."},{"japanese":"これは水ではありません。","reading":"これはみずではありません。","english":"This is not water."}]') ON CONFLICT DO NOTHING;
INSERT INTO "GrammarLesson" ("id", "level", "title", "meaning", "structure", "examples") VALUES ('n5_g003', 'N5', '〜が', 'Subject marker (identifying the subject)', 'Noun が', '[{"japanese":"猫がいます。","reading":"ねこがいます。","english":"There is a cat."},{"japanese":"だれが来ますか。","reading":"だれがきますか。","english":"Who is coming?"}]') ON CONFLICT DO NOTHING;
INSERT INTO "GrammarLesson" ("id", "level", "title", "meaning", "structure", "examples") VALUES ('n5_g004', 'N5', '〜を', 'Direct object marker', 'Noun を Verb', '[{"japanese":"りんごを食べる。","reading":"りんごをたべる。","english":"I eat an apple."},{"japanese":"本を読みます。","reading":"ほんをよみます。","english":"I read a book."}]') ON CONFLICT DO NOTHING;
INSERT INTO "GrammarLesson" ("id", "level", "title", "meaning", "structure", "examples") VALUES ('n5_g005', 'N5', '〜に', 'Destination / time / purpose marker', 'Noun に Verb', '[{"japanese":"学校に行く。","reading":"がっこうにいく。","english":"I go to school."},{"japanese":"六時に起きる。","reading":"ろくじにおきる。","english":"I wake up at 6 o''clock."}]') ON CONFLICT DO NOTHING;
INSERT INTO "GrammarLesson" ("id", "level", "title", "meaning", "structure", "examples") VALUES ('n5_g006', 'N5', '〜で', 'Location of action / means / tool', 'Noun で Verb', '[{"japanese":"図書館で勉強する。","reading":"としょかんでべんきょうする。","english":"I study at the library."},{"japanese":"はしで食べる。","reading":"はしでたべる。","english":"I eat with chopsticks."}]') ON CONFLICT DO NOTHING;
INSERT INTO "GrammarLesson" ("id", "level", "title", "meaning", "structure", "examples") VALUES ('n5_g007', 'N5', '〜と', 'Together with / and', 'Noun と Noun / Noun と Verb', '[{"japanese":"友だちと行く。","reading":"ともだちといく。","english":"I go with a friend."},{"japanese":"りんごとみかん。","reading":"りんごとみかん。","english":"Apple and orange."}]') ON CONFLICT DO NOTHING;
INSERT INTO "GrammarLesson" ("id", "level", "title", "meaning", "structure", "examples") VALUES ('n5_g008', 'N5', '〜も', 'Also / too', 'Noun も', '[{"japanese":"私も学生です。","reading":"わたしもがくせいです。","english":"I am also a student."},{"japanese":"これもください。","reading":"これもください。","english":"This one too, please."}]') ON CONFLICT DO NOTHING;
INSERT INTO "GrammarLesson" ("id", "level", "title", "meaning", "structure", "examples") VALUES ('n5_g009', 'N5', '〜の', 'Possessive / modifier particle', 'Noun の Noun', '[{"japanese":"私の本です。","reading":"わたしのほんです。","english":"It is my book."},{"japanese":"日本語の先生。","reading":"にほんごのせんせい。","english":"Japanese teacher."}]') ON CONFLICT DO NOTHING;
INSERT INTO "GrammarLesson" ("id", "level", "title", "meaning", "structure", "examples") VALUES ('n5_g010', 'N5', '〜ている', 'Ongoing action / current state', 'Verb (te-form) + いる', '[{"japanese":"食べている。","reading":"たべている。","english":"I am eating."},{"japanese":"住んでいる。","reading":"すんでいる。","english":"I live (somewhere)."}]') ON CONFLICT DO NOTHING;
INSERT INTO "GrammarLesson" ("id", "level", "title", "meaning", "structure", "examples") VALUES ('n5_g011', 'N5', '〜たい', 'Want to do (attached to verb stem)', 'Verb stem + たい', '[{"japanese":"水が飲みたい。","reading":"みずがのみたい。","english":"I want to drink water."},{"japanese":"行きたいです。","reading":"いきたいです。","english":"I want to go."}]') ON CONFLICT DO NOTHING;
INSERT INTO "GrammarLesson" ("id", "level", "title", "meaning", "structure", "examples") VALUES ('n5_g012', 'N5', '〜ません', 'Negative polite form of a verb', 'Verb (masu-stem) + ません', '[{"japanese":"食べません。","reading":"たべません。","english":"I do not eat."},{"japanese":"行きません。","reading":"いきません。","english":"I am not going."}]') ON CONFLICT DO NOTHING;
INSERT INTO "GrammarLesson" ("id", "level", "title", "meaning", "structure", "examples") VALUES ('n5_g013', 'N5', '〜ましょう', 'Let''s do (volitional polite)', 'Verb (masu-stem) + ましょう', '[{"japanese":"食べましょう。","reading":"たべましょう。","english":"Let''s eat."},{"japanese":"行きましょう。","reading":"いきましょう。","english":"Let''s go."}]') ON CONFLICT DO NOTHING;
INSERT INTO "GrammarLesson" ("id", "level", "title", "meaning", "structure", "examples") VALUES ('n5_g014', 'N5', '〜から', 'Because / since (reason)', 'Sentence から、Sentence', '[{"japanese":"寒いから、家にいる。","reading":"さむいから、いえにいる。","english":"Because it''s cold, I stay home."},{"japanese":"忙しいから、行けない。","reading":"いそがしいから、いけない。","english":"Because I''m busy, I can''t go."}]') ON CONFLICT DO NOTHING;
INSERT INTO "GrammarLesson" ("id", "level", "title", "meaning", "structure", "examples") VALUES ('n5_g015', 'N5', '〜より', 'Comparison (A is more... than B)', 'Noun より Noun のほうが', '[{"japanese":"肉より魚のほうが好きです。","reading":"にくよりさかなのほうがすきです。","english":"I prefer fish over meat."},{"japanese":"夏より冬のほうが好きです。","reading":"なつよりふゆのほうがすきです。","english":"I prefer winter over summer."}]') ON CONFLICT DO NOTHING;
INSERT INTO "Verb" ("id", "kanji", "reading", "romaji", "meaning", "verbType", "level", "forms") VALUES ('v_taberu', '食べる', 'たべる', 'taberu', 'to eat', 'ichidan', 'N5', '{"plain":{"japanese":"食べる","reading":"たべる","romaji":"taberu","rule":"Dictionary base form"},"polite":{"japanese":"食べます","reading":"たべます","romaji":"tabemasu","rule":"Drop る + ます"},"plain_negative":{"japanese":"食べない","reading":"たべない","romaji":"tabenai","rule":"Drop る + ない"},"plain_past":{"japanese":"食べた","reading":"たべた","romaji":"tabeta","rule":"Drop る + た"},"polite_past":{"japanese":"食べました","reading":"たべました","romaji":"tabemashita","rule":"Drop る + ました"},"polite_negative":{"japanese":"食べません","reading":"たべません","romaji":"tabemasen","rule":"Drop る + ません"},"polite_past_negative":{"japanese":"食べませんでした","reading":"たべませんでした","romaji":"tabemasendeshita","rule":"Drop る + ませんでした"},"plain_past_negative":{"japanese":"食べなかった","reading":"たべなかった","romaji":"tabenakatta","rule":"Drop る + なかった"},"te_form":{"japanese":"食べて","reading":"たべて","romaji":"tabete","rule":"Drop る + て"},"progressive":{"japanese":"食べている","reading":"たべている","romaji":"tabeteiru","rule":"Te-form + いる"},"potential":{"japanese":"食べられる","reading":"たべられる","romaji":"taberareru","rule":"Drop る + られる"},"passive":{"japanese":"食べられる","reading":"たべられる","romaji":"taberareru","rule":"Drop る + られる"},"causative":{"japanese":"食べさせる","reading":"たべさせる","romaji":"tabesaseru","rule":"Drop る + させる"},"volitional":{"japanese":"食べよう","reading":"たべよう","romaji":"tabeyou","rule":"Drop る + よう"},"imperative":{"japanese":"食べろ","reading":"たべろ","romaji":"tabero","rule":"Drop る + ろ"}}') ON CONFLICT DO NOTHING;
INSERT INTO "Verb" ("id", "kanji", "reading", "romaji", "meaning", "verbType", "level", "forms") VALUES ('v_nomu', '飲む', 'のむ', 'nomu', 'to drink', 'godan', 'N5', '{"plain":{"japanese":"飲む","reading":"のむ","romaji":"nomu","rule":"Dictionary base form"},"polite":{"japanese":"飲みます","reading":"のみます","romaji":"nomimasu","rule":"む ➔ み + ます"},"plain_negative":{"japanese":"飲まない","reading":"のまない","romaji":"nomanai","rule":"む ➔ ま + ない"},"plain_past":{"japanese":"飲んだ","reading":"のんだ","romaji":"nonda","rule":"む ➔ んだ"},"polite_past":{"japanese":"飲みました","reading":"のみました","romaji":"nomimashita","rule":"む ➔ み + ました"},"polite_negative":{"japanese":"飲みません","reading":"のみません","romaji":"nomimasen","rule":"む ➔ み + ません"},"polite_past_negative":{"japanese":"飲みませんでした","reading":"のみませんでした","romaji":"nomimasendeshita","rule":"む ➔ み + ませんでした"},"plain_past_negative":{"japanese":"飲まなかった","reading":"のまなかった","romaji":"nomanakatta","rule":"む ➔ ま + なかった"},"te_form":{"japanese":"飲んで","reading":"のんで","romaji":"nonde","rule":"む ➔ んで"},"progressive":{"japanese":"飲んでいる","reading":"のんでいる","romaji":"nondeiru","rule":"Te-form + いる"},"potential":{"japanese":"飲める","reading":"のめる","romaji":"nomeru","rule":"む ➔ め + る"},"passive":{"japanese":"飲まれる","reading":"のまれる","romaji":"nomareru","rule":"む ➔ ま + れる"},"causative":{"japanese":"飲ませる","reading":"のませる","romaji":"nomaseru","rule":"む ➔ ま + せる"},"volitional":{"japanese":"飲もう","reading":"のもう","romaji":"nomou","rule":"む ➔ も + う"},"imperative":{"japanese":"飲め","reading":"のめ","romaji":"nome","rule":"む ➔ め"}}') ON CONFLICT DO NOTHING;
INSERT INTO "Verb" ("id", "kanji", "reading", "romaji", "meaning", "verbType", "level", "forms") VALUES ('v_iku', '行く', 'いく', 'iku', 'to go', 'godan', 'N5', '{"plain":{"japanese":"行く","reading":"いく","romaji":"iku","rule":"Dictionary base form"},"polite":{"japanese":"行きます","reading":"いきます","romaji":"ikimasu","rule":"く ➔ き + ます"},"plain_negative":{"japanese":"行かない","reading":"いかない","romaji":"ikanai","rule":"く ➔ か + ない"},"plain_past":{"japanese":"行った","reading":"いった","romaji":"itta","rule":"Special: 行く ➔ 行った"},"polite_past":{"japanese":"行きました","reading":"いきました","romaji":"ikimashita","rule":"く ➔ き + ました"},"polite_negative":{"japanese":"行きません","reading":"いきません","romaji":"ikimasen","rule":"く ➔ き + ません"},"polite_past_negative":{"japanese":"行きませんでした","reading":"いきませんでした","romaji":"ikimasendeshita","rule":"く ➔ き + ませんでした"},"plain_past_negative":{"japanese":"行かなかった","reading":"いかなかった","romaji":"ikanakatta","rule":"く ➔ か + なかった"},"te_form":{"japanese":"行って","reading":"いって","romaji":"itte","rule":"Special: 行く ➔ 行って"},"progressive":{"japanese":"行っている","reading":"いっている","romaji":"itteiru","rule":"Te-form + いる"},"potential":{"japanese":"行ける","reading":"いける","romaji":"ikeru","rule":"く ➔ け + る"},"passive":{"japanese":"行かれる","reading":"いかれる","romaji":"ikareru","rule":"く ➔ か + れる"},"causative":{"japanese":"行かせる","reading":"いかせる","romaji":"ikaseru","rule":"く ➔ か + せる"},"volitional":{"japanese":"行こう","reading":"いこう","romaji":"ikou","rule":"く ➔ こ + う"},"imperative":{"japanese":"行け","reading":"いけ","romaji":"ike","rule":"く ➔ け"}}') ON CONFLICT DO NOTHING;
INSERT INTO "Verb" ("id", "kanji", "reading", "romaji", "meaning", "verbType", "level", "forms") VALUES ('v_suru', 'する', 'する', 'suru', 'to do', 'irregular', 'N5', '{"plain":{"japanese":"する","reading":"する","romaji":"suru","rule":"Dictionary base form"},"polite":{"japanese":"します","reading":"します","romaji":"shimasu","rule":"Irregular: します"},"plain_negative":{"japanese":"しない","reading":"しない","romaji":"shinai","rule":"Irregular: しない"},"plain_past":{"japanese":"した","reading":"した","romaji":"shita","rule":"Irregular: した"},"polite_past":{"japanese":"しました","reading":"しました","romaji":"shimashita","rule":"Irregular: しました"},"polite_negative":{"japanese":"しません","reading":"しません","romaji":"shimasen","rule":"Irregular: しません"},"polite_past_negative":{"japanese":"しませんでした","reading":"しませんでした","romaji":"shimasendeshita","rule":"Irregular: しませんでした"},"plain_past_negative":{"japanese":"しなかった","reading":"しなかった","romaji":"shinakatta","rule":"Irregular: しなかった"},"te_form":{"japanese":"して","reading":"して","romaji":"shite","rule":"Irregular: して"},"progressive":{"japanese":"している","reading":"している","romaji":"shiteiru","rule":"Te-form + いる"},"potential":{"japanese":"できる","reading":"できる","romaji":"dekiru","rule":"Irregular: できる"},"passive":{"japanese":"される","reading":"される","romaji":"sareru","rule":"Irregular: される"},"causative":{"japanese":"させる","reading":"させる","romaji":"saseru","rule":"Irregular: させる"},"volitional":{"japanese":"しよう","reading":"しよう","romaji":"shiyou","rule":"Irregular: しよう"},"imperative":{"japanese":"しろ","reading":"しろ","romaji":"shiro","rule":"Irregular: しろ"}}') ON CONFLICT DO NOTHING;
INSERT INTO "Verb" ("id", "kanji", "reading", "romaji", "meaning", "verbType", "level", "forms") VALUES ('v_kuru', '来る', 'くる', 'kuru', 'to come', 'irregular', 'N5', '{"plain":{"japanese":"来る","reading":"くる","romaji":"kuru","rule":"Dictionary base form"},"polite":{"japanese":"来ます","reading":"きます","romaji":"kimasu","rule":"Irregular: きます"},"plain_negative":{"japanese":"来ない","reading":"こない","romaji":"konai","rule":"Irregular: こない"},"plain_past":{"japanese":"来た","reading":"きた","romaji":"kita","rule":"Irregular: きた"},"polite_past":{"japanese":"来ました","reading":"きました","romaji":"kimashita","rule":"Irregular: きました"},"polite_negative":{"japanese":"来ません","reading":"きません","romaji":"kimasen","rule":"Irregular: きません"},"polite_past_negative":{"japanese":"来ませんでした","reading":"きませんでした","romaji":"kimasendeshita","rule":"Irregular: きませんでした"},"plain_past_negative":{"japanese":"来なかった","reading":"こなかった","romaji":"konakatta","rule":"Irregular: こなかった"},"te_form":{"japanese":"来て","reading":"きて","romaji":"kite","rule":"Irregular: きて"},"progressive":{"japanese":"来ている","reading":"きている","romaji":"kiteiru","rule":"Te-form + いる"},"potential":{"japanese":"来られる","reading":"こられる","romaji":"korareru","rule":"Irregular: こられる"},"passive":{"japanese":"来られる","reading":"こられる","romaji":"korareru","rule":"Irregular: こられる"},"causative":{"japanese":"来させる","reading":"こさせる","romaji":"kosaseru","rule":"Irregular: こさせる"},"volitional":{"japanese":"来よう","reading":"こよう","romaji":"koyou","rule":"Irregular: こよう"},"imperative":{"japanese":"来い","reading":"こい","romaji":"koi","rule":"Irregular: こい"}}') ON CONFLICT DO NOTHING;
INSERT INTO "Verb" ("id", "kanji", "reading", "romaji", "meaning", "verbType", "level", "forms") VALUES ('v_miru', '見る', 'みる', 'miru', 'to see, to look', 'ichidan', 'N5', '{"plain":{"japanese":"見る","reading":"みる","romaji":"miru","rule":"Dictionary base form"},"polite":{"japanese":"見ます","reading":"みます","romaji":"mimasu","rule":"Drop る + ます"},"plain_negative":{"japanese":"見ない","reading":"みない","romaji":"minai","rule":"Drop る + ない"},"plain_past":{"japanese":"見た","reading":"みた","romaji":"mita","rule":"Drop る + た"},"polite_past":{"japanese":"見ました","reading":"みました","romaji":"mimashita","rule":"Drop る + ました"},"polite_negative":{"japanese":"見ません","reading":"みません","romaji":"mimasen","rule":"Drop る + ません"},"polite_past_negative":{"japanese":"見ませんでした","reading":"みませんでした","romaji":"mimasendeshita","rule":"Drop る + ませんでした"},"plain_past_negative":{"japanese":"見なかった","reading":"みなかった","romaji":"minakatta","rule":"Drop る + なかった"},"te_form":{"japanese":"見て","reading":"みて","romaji":"mite","rule":"Drop る + て"},"progressive":{"japanese":"見ている","reading":"みている","romaji":"miteiru","rule":"Te-form + いる"},"potential":{"japanese":"見られる","reading":"みられる","romaji":"mirareru","rule":"Drop る + られる"},"passive":{"japanese":"見られる","reading":"みられる","romaji":"mirareru","rule":"Drop る + られる"},"causative":{"japanese":"見させる","reading":"みさせる","romaji":"misaseru","rule":"Drop る + させる"},"volitional":{"japanese":"見よう","reading":"みよう","romaji":"miyou","rule":"Drop る + よう"},"imperative":{"japanese":"見ろ","reading":"みろ","romaji":"miro","rule":"Drop る + ろ"}}') ON CONFLICT DO NOTHING;
INSERT INTO "Verb" ("id", "kanji", "reading", "romaji", "meaning", "verbType", "level", "forms") VALUES ('v_hanasu', '話す', 'はなす', 'hanasu', 'to speak, to talk', 'godan', 'N5', '{"plain":{"japanese":"話す","reading":"はなす","romaji":"hanasu","rule":"Dictionary base form"},"polite":{"japanese":"話します","reading":"はなします","romaji":"hanashimasu","rule":"す ➔ し + ます"},"plain_negative":{"japanese":"話さない","reading":"はなさない","romaji":"hanasanai","rule":"す ➔ さ + ない"},"plain_past":{"japanese":"話した","reading":"はなした","romaji":"hanashita","rule":"す ➔ した"},"polite_past":{"japanese":"話しました","reading":"はなしました","romaji":"hanashimashita","rule":"す ➔ し + ました"},"polite_negative":{"japanese":"話しません","reading":"はなしません","romaji":"hanashimasen","rule":"す ➔ し + ません"},"polite_past_negative":{"japanese":"話しませんでした","reading":"はなしませんでした","romaji":"hanashimasendeshita","rule":"す ➔ し + ませんでした"},"plain_past_negative":{"japanese":"話さなかった","reading":"はなさなかった","romaji":"hanasanakatta","rule":"す ➔ さ + なかった"},"te_form":{"japanese":"話して","reading":"はなして","romaji":"hanashite","rule":"す ➔ して"},"progressive":{"japanese":"話している","reading":"はなしている","romaji":"hanashiteiru","rule":"Te-form + いる"},"potential":{"japanese":"話せる","reading":"はなせる","romaji":"hanaseru","rule":"す ➔ せ + る"},"passive":{"japanese":"話される","reading":"はなされる","romaji":"hanasareru","rule":"す ➔ さ + れる"},"causative":{"japanese":"話させる","reading":"はなさせる","romaji":"hanasaseru","rule":"す ➔ さ + せる"},"volitional":{"japanese":"話そう","reading":"はなそう","romaji":"hanasou","rule":"す ➔ そ + う"},"imperative":{"japanese":"話せ","reading":"はなせ","romaji":"hanase","rule":"す ➔ せ"}}') ON CONFLICT DO NOTHING;
INSERT INTO "Verb" ("id", "kanji", "reading", "romaji", "meaning", "verbType", "level", "forms") VALUES ('v_kaku', '書く', 'かく', 'kaku', 'to write', 'godan', 'N5', '{"plain":{"japanese":"書く","reading":"かく","romaji":"kaku","rule":"Dictionary base form"},"polite":{"japanese":"書きます","reading":"かきます","romaji":"kakimasu","rule":"く ➔ き + ます"},"plain_negative":{"japanese":"書かない","reading":"かかない","romaji":"kakanai","rule":"く ➔ か + ない"},"plain_past":{"japanese":"書いた","reading":"かいた","romaji":"kaita","rule":"く ➔ いた"},"polite_past":{"japanese":"書きました","reading":"かきました","romaji":"kakimashita","rule":"く ➔ き + ました"},"polite_negative":{"japanese":"書きません","reading":"かきません","romaji":"kakimasen","rule":"く ➔ き + ません"},"polite_past_negative":{"japanese":"書きませんでした","reading":"かきませんでした","romaji":"kakimasendeshita","rule":"く ➔ き + ませんでした"},"plain_past_negative":{"japanese":"書かなかった","reading":"かなか​​った","romaji":"kakanakatta","rule":"く ➔ か + なかった"},"te_form":{"japanese":"書いて","reading":"かいて","romaji":"kaite","rule":"く ➔ いて"},"progressive":{"japanese":"書いている","reading":"かいている","romaji":"kaiteiru","rule":"Te-form + いる"},"potential":{"japanese":"書ける","reading":"かける","romaji":"kakeru","rule":"く ➔ け + る"},"passive":{"japanese":"書かれる","reading":"かかれる","romaji":"kakareru","rule":"く ➔ か + れる"},"causative":{"japanese":"書かせる","reading":"かかせる","romaji":"kakaseru","rule":"く ➔ か + せる"},"volitional":{"japanese":"書こう","reading":"かこう","romaji":"kakou","rule":"く ➔ こ + う"},"imperative":{"japanese":"書け","reading":"かけ","romaji":"kake","rule":"く ➔ け"}}') ON CONFLICT DO NOTHING;
INSERT INTO "Verb" ("id", "kanji", "reading", "romaji", "meaning", "verbType", "level", "forms") VALUES ('v_kiku', '聞く', 'きく', 'kiku', 'to listen, to hear, to ask', 'godan', 'N5', '{"plain":{"japanese":"聞く","reading":"きく","romaji":"kiku","rule":"Dictionary base form"},"polite":{"japanese":"聞きます","reading":"ききます","romaji":"kikimasu","rule":"く ➔ き + ます"},"plain_negative":{"japanese":"聞かない","reading":"きかない","romaji":"kikanai","rule":"く ➔ か + ない"},"plain_past":{"japanese":"聞いた","reading":"きいた","romaji":"kiita","rule":"く ➔ いた"},"polite_past":{"japanese":"聞きました","reading":"ききました","romaji":"kikimashita","rule":"く ➔ き + ました"},"polite_negative":{"japanese":"聞きません","reading":"ききません","romaji":"kikimasen","rule":"く ➔ き + ません"},"polite_past_negative":{"japanese":"聞きませんでした","reading":"ききませんでした","romaji":"kikimasendeshita","rule":"く ➔ き + ませんでした"},"plain_past_negative":{"japanese":"聞かなかった","reading":"きかなかった","romaji":"kikanakatta","rule":"く ➔ か + なかった"},"te_form":{"japanese":"聞いて","reading":"きいて","romaji":"kiite","rule":"く ➔ いて"},"progressive":{"japanese":"聞いている","reading":"きいている","romaji":"kiiteiru","rule":"Te-form + いる"},"potential":{"japanese":"聞ける","reading":"きける","romaji":"kikeru","rule":"く ➔ け + る"},"passive":{"japanese":"聞かれる","reading":"きかれる","romaji":"kikareru","rule":"く ➔ か + れる"},"causative":{"japanese":"聞かせる","reading":"きかせる","romaji":"kikaseru","rule":"く ➔ か + せる"},"volitional":{"japanese":"聞こう","reading":"きこう","romaji":"kikou","rule":"く ➔ こ + う"},"imperative":{"japanese":"聞け","reading":"きけ","romaji":"kike","rule":"く ➔ け"}}') ON CONFLICT DO NOTHING;
INSERT INTO "Verb" ("id", "kanji", "reading", "romaji", "meaning", "verbType", "level", "forms") VALUES ('v_kau', '買う', 'かう', 'kau', 'to buy', 'godan', 'N5', '{"plain":{"japanese":"買う","reading":"かう","romaji":"kau","rule":"Dictionary base form"},"polite":{"japanese":"買います","reading":"かいます","romaji":"kaimasu","rule":"う ➔ い + ます"},"plain_negative":{"japanese":"買わない","reading":"かわない","romaji":"kawanai","rule":"う ➔ わ + ない"},"plain_past":{"japanese":"買った","reading":"かった","romaji":"katta","rule":"う ➔ った"},"polite_past":{"japanese":"買いました","reading":"かいました","romaji":"kaimashita","rule":"う ➔ い + ました"},"polite_negative":{"japanese":"買いません","reading":"かいません","romaji":"kaimasen","rule":"う ➔ い + ません"},"polite_past_negative":{"japanese":"買いませんでした","reading":"かいませんでした","romaji":"kaimasendeshita","rule":"う ➔ い + ませんでした"},"plain_past_negative":{"japanese":"買わなかった","reading":"かわなかった","romaji":"kawanakatta","rule":"う ➔ わ + なかった"},"te_form":{"japanese":"買って","reading":"かって","romaji":"katte","rule":"う ➔ って"},"progressive":{"japanese":"買っている","reading":"かっている","romaji":"katteiru","rule":"Te-form + いる"},"potential":{"japanese":"買える","reading":"かえる","romaji":"kaeru","rule":"う ➔ え + る"},"passive":{"japanese":"買われる","reading":"かわれる","romaji":"kawareru","rule":"う ➔ わ + れる"},"causative":{"japanese":"買わせる","reading":"かわせる","romaji":"kawaseru","rule":"う ➔ わ + せる"},"volitional":{"japanese":"買おう","reading":"かおう","romaji":"kaou","rule":"う ➔ お + う"},"imperative":{"japanese":"買え","reading":"かえ","romaji":"kae","rule":"う ➔ え"}}') ON CONFLICT DO NOTHING;
INSERT INTO "ReadingStory" ("id", "level", "titleJapanese", "titleRomaji", "titleEnglish", "description", "readTime", "pixelArtEmoji", "category", "isLocked", "sentences", "questions") VALUES ('story_tama_me', 'N5', 'タマと わたし', 'Tama to Watashi', 'Tama and Me', 'A short story about a student and her friendly cat Tama.', '~2 min', '🐱', 'Daily Life', false, '[{"id":"s1","fullJapanese":"わたしは まいあさ 七時（しちじ）に おきます。","fullEnglish":"I wake up at 7:00 every morning.","tokens":[{"text":"わたし","meaning":"I / me"},{"text":"は","grammarHint":"Topic marker particle"},{"text":"まいあさ","meaning":"every morning"},{"text":"七時","furigana":"しちじ","meaning":"7 o''clock"},{"text":"に","grammarHint":"Time particle"},{"text":"おきます","meaning":"to wake up (polite)"},{"text":"。"}]},{"id":"s2","fullJapanese":"わたしの ねこは タマです。","fullEnglish":"My cat''s name is Tama.","tokens":[{"text":"わたし","meaning":"I"},{"text":"の","grammarHint":"Possessive particle ''s"},{"text":"ねこ","meaning":"cat"},{"text":"は","grammarHint":"Topic marker"},{"text":"タマ","meaning":"Tama (name)"},{"text":"です","meaning":"is / to be (polite)"},{"text":"。"}]},{"id":"s3","fullJapanese":"タマは しろくて、とても かわいいです。","fullEnglish":"Tama is white and very cute.","tokens":[{"text":"タマ","meaning":"Tama"},{"text":"は","grammarHint":"Topic marker"},{"text":"しろくて","meaning":"white (te-form adjective)"},{"text":"、"},{"text":"とても","meaning":"very"},{"text":"かわいい","meaning":"cute"},{"text":"です","meaning":"is (polite)"},{"text":"。"}]},{"id":"s4","fullJapanese":"タマは さかなと みるくが だいすきです。","fullEnglish":"Tama loves fish and milk.","tokens":[{"text":"タマ","meaning":"Tama"},{"text":"は","grammarHint":"Topic marker"},{"text":"さかな","meaning":"fish"},{"text":"と","grammarHint":"And / with"},{"text":"みるく","meaning":"milk"},{"text":"が","grammarHint":"Subject marker for likes"},{"text":"だいすき","meaning":"love / like very much"},{"text":"です","meaning":"is"},{"text":"。"}]},{"id":"s5","fullJapanese":"いっしょに こうえんへ いきます。","fullEnglish":"We go to the park together.","tokens":[{"text":"いっしょに","meaning":"together"},{"text":"こうえん","meaning":"park"},{"text":"へ","grammarHint":"Direction particle ''to''"},{"text":"いきます","meaning":"to go (polite)"},{"text":"。"}]}]', '[{"question":"何時に おきますか？ (What time do they wake up?)","options":["六時 (6:00)","七時 (7:00)","八時 (8:00)","九時 (9:00)"],"correctIndex":1,"explanation":"The story states: わたしは まいあさ 七時（しちじ）に おきます (I wake up at 7:00 every morning)."},{"question":"タマは なにが すきですか？ (What does Tama like?)","options":["にく (Meat)","さかなと みるく (Fish and Milk)","ぱん (Bread)","おちゃ (Tea)"],"correctIndex":1,"explanation":"The story states: タマは さかなと みるくが だいすきです (Tama loves fish and milk)."}]') ON CONFLICT DO NOTHING;
INSERT INTO "ReadingStory" ("id", "level", "titleJapanese", "titleRomaji", "titleEnglish", "description", "readTime", "pixelArtEmoji", "category", "isLocked", "sentences", "questions") VALUES ('story_my_house', 'N5', 'わたしの いえ', 'Watashi no Ie', 'My House', 'A short story about the rooms and daily objects inside a student''s home.', '~2 min', '🏠', 'Home', false, '[{"id":"h1","fullJapanese":"これは わたしの いえです。","fullEnglish":"This is my house.","tokens":[{"text":"これ","meaning":"this"},{"text":"は","grammarHint":"Topic marker"},{"text":"わたし","meaning":"I"},{"text":"の","grammarHint":"Possessive ''s"},{"text":"いえ","meaning":"house / home"},{"text":"です","meaning":"is"},{"text":"。"}]},{"id":"h2","fullJapanese":"いえの なかに へやが 三つ（みっつ）あります。","fullEnglish":"Inside the house, there are three rooms.","tokens":[{"text":"いえ","meaning":"house"},{"text":"の","grammarHint":"Possessive / connection"},{"text":"なか","meaning":"inside"},{"text":"に","grammarHint":"Location particle"},{"text":"へや","meaning":"room"},{"text":"が","grammarHint":"Subject marker"},{"text":"三つ","furigana":"みっつ","meaning":"three (things)"},{"text":"あります","meaning":"there is / exist (inanimate)"},{"text":"。"}]},{"id":"h3","fullJapanese":"わたしの へやには つくえと ほん棚（だな）があります。","fullEnglish":"In my room, there is a desk and a bookshelf.","tokens":[{"text":"わたし","meaning":"I"},{"text":"の","grammarHint":"Possessive"},{"text":"へや","meaning":"room"},{"text":"には","grammarHint":"In (location topic)"},{"text":"つくえ","meaning":"desk"},{"text":"と","grammarHint":"And"},{"text":"ほん棚","furigana":"ほんだな","meaning":"bookshelf"},{"text":"が","grammarHint":"Subject marker"},{"text":"あります","meaning":"there is"},{"text":"。"}]},{"id":"h4","fullJapanese":"まいにち つくえで にほんごを べんきょうします。","fullEnglish":"Every day, I study Japanese at my desk.","tokens":[{"text":"まいにち","meaning":"every day"},{"text":"つくえ","meaning":"desk"},{"text":"で","grammarHint":"Action location particle ''at''"},{"text":"にほんご","meaning":"Japanese language"},{"text":"を","grammarHint":"Direct object marker"},{"text":"べんきょうします","meaning":"to study (polite)"},{"text":"。"}]}]', '[{"question":"へやは いくつ ありますか？ (How many rooms are there?)","options":["一つ (1)","二つ (2)","三つ (3)","四つ (4)"],"correctIndex":2,"explanation":"The story states: へやが 三つ（みっつ）あります (There are 3 rooms)."}]') ON CONFLICT DO NOTHING;
INSERT INTO "ReadingStory" ("id", "level", "titleJapanese", "titleRomaji", "titleEnglish", "description", "readTime", "pixelArtEmoji", "category", "isLocked", "sentences", "questions") VALUES ('story_morning_routine', 'N5', '朝の様子', 'Asa no Yousu', 'Daily Morning', 'A short story about a student''s morning routine before going to school.', '~2 min', '🌅', 'Daily Life', false, '[{"id":"m1","fullJapanese":"あさ、ごはんを たべて、おちゃを のみます。","fullEnglish":"In the morning, I eat a meal and drink green tea.","tokens":[{"text":"あさ","meaning":"morning"},{"text":"、"},{"text":"ごはん","meaning":"meal / rice"},{"text":"を","grammarHint":"Object marker"},{"text":"たべて","meaning":"eat (te-form)"},{"text":"、"},{"text":"おちゃ","meaning":"green tea"},{"text":"を","grammarHint":"Object marker"},{"text":"のみます","meaning":"to drink (polite)"},{"text":"。"}]},{"id":"m2","fullJapanese":"八時半（はちじはん）に がっこうへ いきます。","fullEnglish":"At 8:30, I go to school.","tokens":[{"text":"八時半","furigana":"はちじはん","meaning":"8:30"},{"text":"に","grammarHint":"Time particle"},{"text":"がっこう","meaning":"school"},{"text":"へ","grammarHint":"Direction ''to''"},{"text":"いきます","meaning":"to go"},{"text":"。"}]}]', '[{"question":"何時に がっこうへ いきますか？ (What time do they go to school?)","options":["七時 (7:00)","八時 (8:00)","八時半 (8:30)","九時 (9:00)"],"correctIndex":2,"explanation":"The story states: 八時半（はちじはん）に がっこうへ いきます。"}]') ON CONFLICT DO NOTHING;
INSERT INTO "ReadingStory" ("id", "level", "titleJapanese", "titleRomaji", "titleEnglish", "description", "readTime", "pixelArtEmoji", "category", "isLocked", "sentences", "questions") VALUES ('story_ramen_shop', 'N4', 'ラーメン屋で', 'Raamenya de', 'At the Ramen Shop', 'Ordering a hot bowl of ramen in Tokyo with friendly dialogue.', '~3 min', '🍜', 'Food', false, '[{"id":"r1","fullJapanese":"駅の近くにおいしいラーメン屋があります。","fullEnglish":"There is a delicious ramen shop near the train station.","tokens":[{"text":"駅","furigana":"えき","meaning":"station"},{"text":"の","grammarHint":"Possessive"},{"text":"近く","furigana":"ちかく","meaning":"nearby / vicinity"},{"text":"に","grammarHint":"Location particle"},{"text":"おいしい","meaning":"delicious"},{"text":"ラーメン屋","furigana":"ラーメンや","meaning":"ramen restaurant"},{"text":"が","grammarHint":"Subject marker"},{"text":"あります","meaning":"there is"},{"text":"。"}]},{"id":"r2","fullJapanese":"「いらっしゃいませ！何名様ですか？」と店員が言いました。","fullEnglish":"\"Welcome! How many people?\" the clerk asked.","tokens":[{"text":"「いらっしゃいませ","meaning":"welcome (shop greeting)"},{"text":"！"},{"text":"何名様","furigana":"なんめいさま","meaning":"how many people (polite)"},{"text":"ですか","meaning":"is it? (question)"},{"text":"？」と","grammarHint":"Quotation particle"},{"text":"店員","furigana":"てんいん","meaning":"clerk / staff"},{"text":"が","grammarHint":"Subject"},{"text":"言いました","furigana":"いいました","meaning":"said"},{"text":"。"}]}]', '[{"question":"ラーメン屋は どこに ありますか？ (Where is the ramen shop?)","options":["駅の近く (Near the station)","学校の中 (Inside the school)","公園の前 (In front of the park)","家の中 (Inside the house)"],"correctIndex":0,"explanation":"The story states: 駅の近くにおいしいラーメン屋があります。"}]') ON CONFLICT DO NOTHING;
