INSERT INTO "DailyBankItem" ("id", "category", "payload") VALUES ('dk-1', 'kanji', '{"kanji":"日","meaning":"Sun / Day","onyomi":"ニチ, ジツ","kunyomi":"ひ, -び, -か","question":"What is the primary meaning of the kanji 「日」?","options":["Sun / Day","Moon / Month","Tree / Wood","Fire"],"answer":"Sun / Day","explanation":"「日」(nichi/hi) represents the Sun or a Day. e.g. 日本 (Nihon / Japan)."}') ON CONFLICT DO NOTHING;
INSERT INTO "DailyBankItem" ("id", "category", "payload") VALUES ('dk-2', 'kanji', '{"kanji":"水","meaning":"Water","onyomi":"スイ","kunyomi":"みず","question":"What is the Onyomi (Chinese-derived reading) of 「水」 (Water)?","options":["スイ (SUI)","モク (MOKU)","カ (KA)","キン (KIN)"],"answer":"スイ (SUI)","explanation":"「水」 has Kunyomi ''みず'' (mizu) and Onyomi ''スイ'' (sui, as in 水曜日 sui-youbi / Wednesday)."}') ON CONFLICT DO NOTHING;
INSERT INTO "DailyBankItem" ("id", "category", "payload") VALUES ('dk-3', 'kanji', '{"kanji":"山","meaning":"Mountain","onyomi":"サン, ザン","kunyomi":"やま","question":"How is 「富士山」 read in Japanese?","options":["ふじさん (Fujisan)","ふじやま (Fujiyama)","ふじかわ (Fujikawa)","ふじうみ (Fujiumi)"],"answer":"ふじさん (Fujisan)","explanation":"富士山 is pronounced ふじさん (Fujisan) using the Onyomi ''サン''."}') ON CONFLICT DO NOTHING;
INSERT INTO "DailyBankItem" ("id", "category", "payload") VALUES ('dk-4', 'kanji', '{"kanji":"友","meaning":"Friend","onyomi":"ユウ","kunyomi":"とも","question":"What is the Kunyomi reading for 「友」 in 「友達」?","options":["とも (tomo)","ゆう (yuu)","あい (ai)","ひと (hito)"],"answer":"とも (tomo)","explanation":"「友達」 is pronounced ともだち (tomodachi), where 友 is read as とも (tomo)."}') ON CONFLICT DO NOTHING;
INSERT INTO "DailyBankItem" ("id", "category", "payload") VALUES ('dk-5', 'kanji', '{"kanji":"学","meaning":"Study / Learning","onyomi":"ガク","kunyomi":"まな・ぶ","question":"Which word means ''Student'' in Japanese?","options":["学生 (がくせい)","先生 (せんせい)","学校 (がっこう)","大学 (だいがく)"],"answer":"学生 (がくせい)","explanation":"「学生」(gakusei) combines 学 (learning) and 生 (person/life) to mean student."}') ON CONFLICT DO NOTHING;
INSERT INTO "DailyBankItem" ("id", "category", "payload") VALUES ('dk-6', 'kanji', '{"kanji":"食","meaning":"Eat / Food","onyomi":"ショク","kunyomi":"た・べる, く・う","question":"What is the verb form of 「食」 meaning ''to eat''?","options":["食べる (たべる)","飲む (のむ)","見る (みる)","行く (いく)"],"answer":"食べる (たべる)","explanation":"「食べる」(taberu) is the Ichidan verb for ''to eat''."}') ON CONFLICT DO NOTHING;
INSERT INTO "DailyBankItem" ("id", "category", "payload") VALUES ('dv-1', 'vocabulary', '{"word":"猫","reading":"ねこ (neko)","question":"What does 「ねこ」(neko) mean in English?","options":["Cat","Dog","Bird","Fish"],"answer":"Cat","explanation":"「猫 / ねこ」(neko) is the Japanese word for cat."}') ON CONFLICT DO NOTHING;
INSERT INTO "DailyBankItem" ("id", "category", "payload") VALUES ('dv-2', 'vocabulary', '{"word":"図書館","reading":"としょかん (toshokan)","question":"Where do you go if someone says: 「図書館へ本を借りに行きます」?","options":["Library","Bookstore","Post Office","Hospital"],"answer":"Library","explanation":"「図書館」(toshokan) means library."}') ON CONFLICT DO NOTHING;
INSERT INTO "DailyBankItem" ("id", "category", "payload") VALUES ('dv-3', 'vocabulary', '{"word":"美味しい","reading":"おいしい (oishii)","question":"Choose the antonym (opposite meaning) of 「美味しい」(delicious):","options":["まずい (mazui / unpalatable)","甘い (amai / sweet)","辛い (karai / spicy)","高い (takai / expensive)"],"answer":"まずい (mazui / unpalatable)","explanation":"「まずい」(mazui) means bad-tasting or unpalatable, the opposite of おいしい."}') ON CONFLICT DO NOTHING;
INSERT INTO "DailyBankItem" ("id", "category", "payload") VALUES ('dv-4', 'vocabulary', '{"word":"約束","reading":"やくそく (yakusoku)","question":"What is the meaning of the word 「約束」(yakusoku)?","options":["Promise / Appointment","Memory","Dream","Rule"],"answer":"Promise / Appointment","explanation":"「約束」(yakusoku) means a promise or an appointment. e.g. 約束を守る (to keep a promise)."}') ON CONFLICT DO NOTHING;
INSERT INTO "DailyBankItem" ("id", "category", "payload") VALUES ('dv-5', 'vocabulary', '{"word":"空港","reading":"くうこう (kuukou)","question":"Which vehicle is associated with 「空港」(kuukou)?","options":["飛行機 (Airplane)","新幹線 (Bullet Train)","船 (Ship)","自転車 (Bicycle)"],"answer":"飛行機 (Airplane)","explanation":"「空港」(kuukou) means airport, where airplanes (飛行機 hikouki) arrive and depart."}') ON CONFLICT DO NOTHING;
INSERT INTO "DailyBankItem" ("id", "category", "payload") VALUES ('dc-1', 'culture', '{"question":"Which polite phrase is traditionally said BEFORE eating a meal in Japan?","options":["いただきます (Itadakimasu)","ごちそうさまでした (Gochisousama deshita)","お邪魔します (Ojamashimasu)","行ってきます (Ittekimasu)"],"answer":"いただきます (Itadakimasu)","explanation":"「いただきます」(Itadakimasu) literally means ''I humbly receive'' and is said before eating."}') ON CONFLICT DO NOTHING;
INSERT INTO "DailyBankItem" ("id", "category", "payload") VALUES ('dc-2', 'culture', '{"question":"What is the traditional Japanese art of paper folding called?","options":["折り紙 (Origami)","生け花 (Ikebana)","書道 (Shodou)","浮世絵 (Ukiyo-e)"],"answer":"折り紙 (Origami)","explanation":"折り紙 (Origami) combines ''ori'' (folding) and ''kami'' (paper)."}') ON CONFLICT DO NOTHING;
INSERT INTO "DailyBankItem" ("id", "category", "payload") VALUES ('dc-3', 'culture', '{"question":"What does the Japanese proverb 「猿も木から落ちる」 (Saru mo ki kara ochiru) mean?","options":["Even experts make mistakes (''Even monkeys fall from trees'')","Practice makes perfect","Patience is a virtue","Actions speak louder than words"],"answer":"Even experts make mistakes (''Even monkeys fall from trees'')","explanation":"This classic proverb reminds us that anyone, even someone skilled like a monkey climbing trees, can occasionally fail."}') ON CONFLICT DO NOTHING;
INSERT INTO "DailyBankItem" ("id", "category", "payload") VALUES ('dc-4', 'culture', '{"question":"What is the four-character idiom 「一期一会」 (Ichigo Ichie) translated as?","options":["Treasure once-in-a-lifetime encounters","Work hard every day","United as one","Calm like a mirror"],"answer":"Treasure once-in-a-lifetime encounters","explanation":"一期一会 (Ichigo Ichie), rooted in the Japanese Tea Ceremony, emphasizes treating every meeting as precious and unique."}') ON CONFLICT DO NOTHING;
